import { useCallback, useEffect, useRef, useState } from 'react';
import { Game } from './game/engine';
import { Input } from './game/input';
import { audio } from './game/audio';
import type { DiffKey, EndStats, HudState } from './game/types';
import { Menu } from './components/Menu';
import { Hud, TouchControls } from './components/Hud';
import { GameOver, PauseMenu } from './components/Overlays';
import './index.css';

type Screen = 'menu' | 'play' | 'pause' | 'over';

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [input, setInput] = useState<Input | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudState | null>(null);
  const [end, setEnd] = useState<EndStats | null>(null);
  const [diff, setDiff] = useState<DiffKey>('normal');
  const [muted, setMuted] = useState(false);
  const [hi, setHi] = useState(0);

  useEffect(() => {
    const inp = new Input();
    inp.attach();
    setInput(inp);
    const g = new Game(canvasRef.current!, inp, {
      onHud: setHud,
      onEnd: s => { setEnd(s); setHi(s.hi); setScreen('over'); },
    });
    gameRef.current = g;
    setHi(g.hi);
    const wrap = wrapRef.current!;
    const fit = () => { const r = wrap.getBoundingClientRect(); g.resize(r.width, r.height); };
    const ro = new ResizeObserver(fit);
    ro.observe(wrap);
    fit();
    g.run();
    return () => { ro.disconnect(); g.destroy(); inp.detach(); audio.dispose(); gameRef.current = null; };
  }, []);

  const play = useCallback(() => {
    (document.activeElement as HTMLElement | null)?.blur?.();
    audio.init();
    gameRef.current?.start(diff);
    setEnd(null);
    setScreen('play');
  }, [diff]);

  const setPaused = useCallback((v: boolean) => {
    if (gameRef.current) gameRef.current.paused = v;
    input?.clear();
    setScreen(v ? 'pause' : 'play');
  }, [input]);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract();
    setHi(gameRef.current?.hi ?? 0);
    setHud(null);
    setScreen('menu');
  }, []);

  const toggleMute = useCallback(() => { setMuted(m => { audio.setMuted(!m); return !m; }); }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code === 'Escape' || e.code === 'KeyP') {
        if (screen === 'play') setPaused(true);
        else if (screen === 'pause') setPaused(false);
      } else if (e.code === 'Enter' && (screen === 'menu' || screen === 'over')) play();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [screen, setPaused, play]);

  return (
    <div ref={wrapRef} className="se-root relative h-full min-h-[100vh] w-full select-none overflow-hidden bg-[#05030f]" style={{ touchAction: 'none' }}>
      <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" />
      {screen === 'menu' && <Menu diff={diff} setDiff={setDiff} hi={hi} muted={muted} onMute={toggleMute} onPlay={play} />}
      {screen !== 'menu' && hud && <Hud hud={hud} muted={muted} onMute={toggleMute} onPause={() => setPaused(true)} />}
      {screen === 'play' && <TouchControls input={input} />}
      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && end && <GameOver s={end} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useState } from 'react';
import type { PointerEvent } from 'react';
import { ArrowBigUp, ChevronDown, ChevronLeft, ChevronRight, Heart, Magnet, Pause, Shield, Star, Volume2, VolumeX, Wind, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { HudState } from '../game/types';
import type { Input } from '../game/input';

interface Props { hud: HudState; muted: boolean; onMute: () => void; onPause: () => void }

const fmt = (t: number) => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;

function Timer({ icon, value, max, color, label }: { icon: JSX.Element; value: number; max: number; color: string; label: string }) {
  return (
    <div title={label} className="se-panel flex items-center gap-2 rounded-full py-1 pl-2 pr-3" style={{ color }}>
      {icon}
      <div className="h-1.5 w-14 overflow-hidden rounded-full bg-white/10">
        <div className="h-full rounded-full" style={{ width: `${Math.min(100, (value / max) * 100)}%`, background: color }} />
      </div>
    </div>
  );
}

export function Hud({ hud, muted, onMute, onPause }: Props) {
  return (
    <div className="pointer-events-none absolute inset-0">
      <div className="absolute left-3 top-3 flex flex-col gap-2 sm:left-4 sm:top-4">
        <div className="se-panel flex items-center gap-4 rounded-2xl px-4 py-2">
          <div>
            <div className="text-[10px] font-bold uppercase tracking-widest text-cyan-300/80">Puntos</div>
            <div className="text-2xl font-black tabular-nums leading-none text-white">{hud.score.toLocaleString('es-ES')}</div>
          </div>
          <div className="h-8 w-px bg-white/15" />
          <div className="flex items-center gap-1.5 text-yellow-200">
            <Star size={18} className="fill-yellow-300 text-yellow-300" />
            <span className="text-lg font-black tabular-nums">{hud.coins}</span>
          </div>
          <div className="flex items-center gap-0.5">
            {Array.from({ length: Math.min(hud.lives, 7) }, (_, i) => (
              <Heart key={i} size={18} className="fill-rose-500 text-rose-300 drop-shadow-[0_0_6px_rgba(255,77,109,0.8)]" />
            ))}
            {hud.lives > 7 && <span className="ml-1 text-xs font-bold text-rose-200">+{hud.lives - 7}</span>}
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          {hud.shield && <div className="se-panel flex items-center gap-1 rounded-full px-3 py-1 text-xs font-bold text-cyan-200"><Shield size={14} /> Escudo</div>}
          {hud.magnet > 0 && <Timer icon={<Magnet size={14} />} value={hud.magnet} max={12} color="#ff5ea8" label="Imán" />}
          {hud.boost > 0 && <Timer icon={<Zap size={14} />} value={hud.boost} max={10} color="#9dff6a" label="Propulsor" />}
          <div className={clsx('se-panel flex items-center gap-1 rounded-full px-3 py-1 text-xs font-bold transition', hud.dashReady ? 'text-cyan-200' : 'text-white/30')}>
            <Wind size={14} /> Dash
          </div>
        </div>
      </div>

      <div className="absolute left-1/2 top-3 hidden w-[min(36vw,420px)] -translate-x-1/2 sm:top-4 md:block">
        <div className="se-chip mb-1 text-center text-[11px] font-bold uppercase tracking-[0.2em] text-indigo-100/90">{hud.sector}</div>
        <div className="relative h-2 rounded-full bg-white/10">
          <div className="h-full rounded-full bg-gradient-to-r from-cyan-400 via-fuchsia-400 to-yellow-300" style={{ width: `${hud.progress * 100}%` }} />
          <div className="absolute -top-1 h-4 w-4 -translate-x-1/2 rounded-full border-2 border-white bg-cyan-300 shadow-[0_0_12px_#7cf7ff]" style={{ left: `${hud.progress * 100}%` }} />
        </div>
      </div>

      <div className="pointer-events-auto absolute right-3 top-3 flex items-center gap-2 sm:right-4 sm:top-4">
        <div className="se-panel rounded-xl px-3 py-1.5 text-right">
          <div className="text-[10px] font-bold uppercase tracking-widest text-pink-300/80">Sector {hud.level}</div>
          <div className="text-sm font-black tabular-nums">{fmt(hud.time)}</div>
        </div>
        <button onClick={onMute} aria-label="Silenciar" className="se-ghost flex h-10 w-10 items-center justify-center rounded-full">
          {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
        </button>
        <button onClick={onPause} aria-label="Pausa" className="se-ghost flex h-10 w-10 items-center justify-center rounded-full">
          <Pause size={18} />
        </button>
      </div>
    </div>
  );
}

// ---------- Controles táctiles ----------
type Hold = 'left' | 'right' | 'down' | 'jump';

export function TouchControls({ input }: { input: Input | null }) {
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));
  const [on, setOn] = useState<Record<Hold, boolean>>({ left: false, right: false, down: false, jump: false });
  if (!touch || !input) return null;

  const set = (k: Hold, v: boolean) => { input.touch[k] = v; setOn(o => ({ ...o, [k]: v })); };
  const hold = (k: Hold, Icon: typeof ChevronLeft, cls: string, label: string) => (
    <button aria-label={label}
      onPointerDown={(e: PointerEvent) => { e.preventDefault(); (e.target as HTMLElement).setPointerCapture?.(e.pointerId); set(k, true); if (k === 'jump') input.press('jump'); }}
      onPointerUp={() => set(k, false)} onPointerCancel={() => set(k, false)} onPointerLeave={() => set(k, false)}
      className={`flex items-center justify-center rounded-full border border-cyan-200/40 text-white backdrop-blur transition ${on[k] ? 'scale-95 bg-cyan-300/40' : 'bg-white/10'} ${cls}`}>
      <Icon size={k === 'jump' ? 34 : 28} />
    </button>
  );

  return (
    <>
      <div className="absolute bottom-6 left-4 flex items-end gap-3">
        {hold('left', ChevronLeft, 'h-16 w-16', 'Izquierda')}
        <div className="flex flex-col items-center gap-2">
          {hold('down', ChevronDown, 'h-11 w-11', 'Bajar')}
        </div>
        {hold('right', ChevronRight, 'h-16 w-16', 'Derecha')}
      </div>
      <div className="absolute bottom-6 right-4 flex items-end gap-3">
        <button aria-label="Dash" onPointerDown={e => { e.preventDefault(); input.press('dash'); }}
          className="flex h-16 w-16 items-center justify-center rounded-full border border-pink-200/50 bg-pink-500/30 text-white backdrop-blur active:scale-95">
          <Wind size={28} />
        </button>
        {hold('jump', ArrowBigUp, 'h-20 w-20 !bg-yellow-400/40 border-yellow-200/60', 'Saltar')}
      </div>
    </>
  );
}

import { useEffect } from 'react';
import type { ReactNode } from 'react';
import { Clock, Home, Play, RotateCcw, Skull, Star, Trophy } from 'lucide-react';
import confetti from 'canvas-confetti';
import type { EndStats } from '../game/types';

function Shell({ children }: { children: ReactNode }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-[#05030f]/65 p-4 backdrop-blur-sm">
      <div className="se-panel se-pop w-full max-w-sm rounded-3xl p-6 text-center">{children}</div>
    </div>
  );
}

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Shell>
      <h2 className="se-title mb-1 text-5xl">PAUSA</h2>
      <p className="mb-5 text-sm text-indigo-200/70">Pulsa P o Esc para continuar</p>
      <div className="flex flex-col gap-3">
        <button onClick={onResume} className="se-btn flex items-center justify-center gap-2 rounded-xl py-3 text-lg"><Play size={20} /> Continuar</button>
        <button onClick={onRestart} className="se-ghost flex items-center justify-center gap-2 rounded-xl py-3 font-bold"><RotateCcw size={18} /> Reiniciar</button>
        <button onClick={onMenu} className="se-ghost flex items-center justify-center gap-2 rounded-xl py-3 font-bold"><Home size={18} /> Menú principal</button>
      </div>
    </Shell>
  );
}

function Stat({ icon, label, value }: { icon: JSX.Element; label: string; value: string }) {
  return (
    <div className="rounded-xl bg-white/5 px-3 py-2 text-left">
      <div className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-widest text-indigo-200/70">{icon}{label}</div>
      <div className="text-lg font-black tabular-nums">{value}</div>
    </div>
  );
}

export function GameOver({ s, onRetry, onMenu }: { s: EndStats; onRetry: () => void; onMenu: () => void }) {
  useEffect(() => {
    if (!s.newRecord) return;
    const end = Date.now() + 1200;
    const id = window.setInterval(() => {
      if (Date.now() > end) { window.clearInterval(id); return; }
      void confetti({ particleCount: 40, spread: 70, startVelocity: 40, origin: { x: Math.random(), y: 0.3 }, colors: ['#7cf7ff', '#ff5ea8', '#ffd23f'] });
    }, 200);
    return () => window.clearInterval(id);
  }, [s.newRecord]);
  const t = `${Math.floor(s.time / 60)}:${String(Math.floor(s.time % 60)).padStart(2, '0')}`;
  return (
    <Shell>
      <div className="mx-auto mb-2 flex h-14 w-14 items-center justify-center rounded-full bg-rose-500/20 text-rose-300"><Skull size={30} /></div>
      <h2 className="se-title mb-1 text-4xl">FIN DE LA MISIÓN</h2>
      {s.newRecord
        ? <p className="se-pulse mb-4 font-black uppercase tracking-widest text-yellow-300">¡Nuevo récord!</p>
        : <p className="mb-4 text-sm text-indigo-200/70">Récord: {s.hi.toLocaleString('es-ES')}</p>}
      <div className="mb-5 text-5xl font-black tabular-nums text-white drop-shadow-[0_0_16px_rgba(124,247,255,0.6)]">{s.score.toLocaleString('es-ES')}</div>
      <div className="mb-5 grid grid-cols-2 gap-2">
        <Stat icon={<Trophy size={12} />} label="Sector" value={String(s.level)} />
        <Stat icon={<Star size={12} />} label="Fragmentos" value={String(s.coins)} />
        <Stat icon={<Skull size={12} />} label="Enemigos" value={String(s.enemies)} />
        <Stat icon={<Clock size={12} />} label="Tiempo" value={t} />
      </div>
      <div className="flex flex-col gap-3">
        <button onClick={onRetry} className="se-btn flex items-center justify-center gap-2 rounded-xl py-3 text-lg"><RotateCcw size={20} /> Reintentar</button>
        <button onClick={onMenu} className="se-ghost flex items-center justify-center gap-2 rounded-xl py-3 font-bold"><Home size={18} /> Menú principal</button>
      </div>
    </Shell>
  );
}

// Dibujo del astronauta y de los enemigos (Canvas 2D vectorial).
import { glow } from './sprites';
import type { Bullet, Enemy, Player } from './types';

function astronaut(ctx: CanvasRenderingContext2D, p: Player, time: number, ghost: boolean) {
  const run = p.onGround && Math.abs(p.vx) > 30 ? Math.sin(p.runT * 18) : 0;
  const air = !p.onGround;
  // mochila
  ctx.fillStyle = ghost ? '#7cf7ff' : '#ff8a3d';
  ctx.beginPath(); ctx.roundRect(-13, -25, 7, 15, 2); ctx.fill();
  if (!ghost) { ctx.fillStyle = '#c4551c'; ctx.fillRect(-13, -14, 7, 3); }
  // piernas
  ctx.fillStyle = ghost ? '#bff' : '#cfd6f5';
  const l1 = air ? -3 : run * 4, l2 = air ? 2 : -run * 4;
  ctx.beginPath(); ctx.roundRect(-6 + l1 * 0.5, -9 - Math.max(0, l1) * 0.4, 5, 9, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(1 + l2 * 0.5, -9 - Math.max(0, l2) * 0.4, 5, 9, 2); ctx.fill();
  if (!ghost) { ctx.fillStyle = '#4b4f7a'; ctx.fillRect(-6 + l1 * 0.5, -2, 5, 2); ctx.fillRect(1 + l2 * 0.5, -2, 5, 2); }
  // cuerpo
  ctx.fillStyle = ghost ? '#dff' : '#f3f5ff';
  ctx.beginPath(); ctx.roundRect(-8, -21, 16, 14, 5); ctx.fill();
  if (!ghost) {
    ctx.fillStyle = '#c8cff0'; ctx.fillRect(-8, -12, 16, 3);
    ctx.fillStyle = '#ff5d73'; ctx.fillRect(1, -18, 4, 3);
    ctx.fillStyle = '#7cf7ff'; ctx.fillRect(-4, -18, 3, 3);
  }
  // brazo
  const arm = air ? -6 : run * 3;
  ctx.fillStyle = ghost ? '#cff' : '#e2e7ff';
  ctx.save(); ctx.translate(2, -18); ctx.rotate((arm * Math.PI) / 18 + (air ? -0.9 : 0.15)); ctx.beginPath(); ctx.roundRect(-2, 0, 5, 9, 2); ctx.fill(); ctx.restore();
  // casco
  ctx.fillStyle = ghost ? '#eff' : '#ffffff';
  ctx.beginPath(); ctx.arc(0, -27, 10, 0, Math.PI * 2); ctx.fill();
  if (!ghost) {
    const vg = ctx.createLinearGradient(-2, -33, 8, -21);
    vg.addColorStop(0, '#5ee7ff'); vg.addColorStop(0.6, '#2a58d6'); vg.addColorStop(1, '#1b1650');
    ctx.fillStyle = vg; ctx.beginPath(); ctx.ellipse(3, -27, 7, 5.5, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.85)'; ctx.beginPath(); ctx.ellipse(1, -29, 2.5, 1.4, -0.5, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#9aa3d8'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(-5, -35); ctx.lineTo(-7, -41); ctx.stroke();
    ctx.globalCompositeOperation = 'lighter';
    const b = 0.6 + Math.sin(time * 8) * 0.4;
    ctx.drawImage(glow('#ffd23f'), -13, -47, 12 * (1 + b * 0.5), 12 * (1 + b * 0.5));
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#ffd23f'; ctx.beginPath(); ctx.arc(-7, -41, 2, 0, Math.PI * 2); ctx.fill();
  }
}

export function drawPlayer(ctx: CanvasRenderingContext2D, p: Player, time: number) {
  if (p.dead) return;
  // estelas del dash
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  for (const t of p.trail) {
    ctx.globalAlpha = t.a * 0.5;
    ctx.save(); ctx.translate(t.x, t.y); ctx.scale(t.face, 1); astronaut(ctx, p, time, true); ctx.restore();
  }
  ctx.restore();
  const cx = p.x + p.w / 2, fy = p.y + p.h;
  // fuego del jetpack
  if (p.flame > 0) {
    ctx.globalCompositeOperation = 'lighter';
    const f = p.flame * (0.8 + Math.random() * 0.4);
    ctx.drawImage(glow('#ff9a3d'), cx - p.face * 9 - 12, fy - 14, 24, 30 * f + 10);
    ctx.drawImage(glow('#ffe66d'), cx - p.face * 9 - 6, fy - 12, 12, 18 * f + 6);
    ctx.globalCompositeOperation = 'source-over';
  }
  ctx.save();
  if (p.invuln > 0 && Math.floor(time * 20) % 2 === 0) ctx.globalAlpha = 0.35;
  ctx.translate(cx, fy); ctx.scale(p.sx * p.face, p.sy);
  astronaut(ctx, p, time, false);
  ctx.restore();
  if (p.shield) {
    ctx.save(); ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.5 + Math.sin(time * 6) * 0.15;
    ctx.drawImage(glow('#5ee7ff'), cx - 30, fy - 46, 60, 60);
    ctx.strokeStyle = '#a8f4ff'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(cx, fy - 16, 25, 0, Math.PI * 2); ctx.stroke();
    ctx.restore();
  }
}

export function drawEnemy(ctx: CanvasRenderingContext2D, e: Enemy, time: number, tx: number, ty: number) {
  const cx = e.x + e.w / 2, by = e.y + e.h, t = e.t;
  ctx.save();
  if (e.kind === 'crawler') {
    const sq = 1 + Math.sin(t * 10) * 0.08;
    ctx.translate(cx, by); ctx.scale(e.dir * (2 - sq), sq);
    ctx.globalCompositeOperation = 'lighter'; ctx.drawImage(glow('#7dff6a'), -22, -30, 44, 40); ctx.globalCompositeOperation = 'source-over';
    const g = ctx.createRadialGradient(-3, -16, 2, 0, -10, 18); g.addColorStop(0, '#d4ff9a'); g.addColorStop(1, '#2f9e3b');
    ctx.fillStyle = g; ctx.beginPath(); ctx.ellipse(0, -9, 14, 11, 0, Math.PI, 0); ctx.lineTo(14, 0); ctx.lineTo(-14, 0); ctx.fill();
    ctx.strokeStyle = '#2f9e3b'; ctx.lineWidth = 2;
    for (const s of [-1, 1]) {
      ctx.beginPath(); ctx.moveTo(s * 4, -18); ctx.lineTo(s * 7 + 3, -27 + Math.sin(t * 6 + s) * 2); ctx.stroke();
      ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(s * 7 + 3, -27 + Math.sin(t * 6 + s) * 2, 4, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = '#111'; ctx.beginPath(); ctx.arc(s * 7 + 4.5, -27 + Math.sin(t * 6 + s) * 2, 2, 0, Math.PI * 2); ctx.fill();
    }
    ctx.fillStyle = '#123d18'; ctx.beginPath(); ctx.arc(7, -7, 3, 0, Math.PI); ctx.fill();
  } else if (e.kind === 'floater') {
    const cy = e.y + e.h / 2;
    ctx.translate(cx, cy);
    ctx.globalCompositeOperation = 'lighter'; ctx.drawImage(glow('#ff5ea8'), -34, -34, 68, 68); ctx.globalCompositeOperation = 'source-over';
    ctx.strokeStyle = '#ff9ccf'; ctx.lineWidth = 2;
    for (let i = -2; i <= 2; i++) {
      ctx.beginPath(); ctx.moveTo(i * 5, 0);
      for (let k = 1; k <= 4; k++) ctx.lineTo(i * 5 + Math.sin(t * 5 + k + i) * 3, k * 5);
      ctx.stroke();
    }
    const g = ctx.createRadialGradient(-4, -8, 2, 0, -2, 16); g.addColorStop(0, '#ffe0f1'); g.addColorStop(1, '#b0287a');
    ctx.fillStyle = g; ctx.beginPath(); ctx.ellipse(0, 0, 15, 13 + Math.sin(t * 5) * 1.5, 0, Math.PI, 0); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#2a0a26'; ctx.beginPath(); ctx.arc(-5, -4, 2.5, 0, Math.PI * 2); ctx.arc(5, -4, 2.5, 0, Math.PI * 2); ctx.fill();
  } else if (e.kind === 'turret') {
    const a = Math.atan2(ty - (e.y + 10), tx - cx), charge = Math.max(0, 1 - e.cool / 0.6);
    ctx.translate(cx, by);
    ctx.fillStyle = '#2a2e4f'; ctx.fillRect(-15, -8, 30, 8);
    ctx.save(); ctx.translate(0, -16); ctx.rotate(a);
    ctx.fillStyle = '#5b628f'; ctx.fillRect(0, -4, 22, 8); ctx.fillStyle = '#ff4d6d'; ctx.fillRect(18, -4, 4, 8); ctx.restore();
    const g = ctx.createLinearGradient(0, -28, 0, -6); g.addColorStop(0, '#c9cff5'); g.addColorStop(1, '#3b4170');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, -8, 14, Math.PI, 0); ctx.fill();
    ctx.globalCompositeOperation = 'lighter';
    ctx.drawImage(glow('#ff4d6d'), -10 - charge * 10, -24 - charge * 10, 20 + charge * 20, 20 + charge * 20);
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#ff4d6d'; ctx.beginPath(); ctx.arc(0, -14, 4, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.translate(cx, by - 11); ctx.rotate(e.x / 14);
    ctx.globalCompositeOperation = 'lighter'; ctx.drawImage(glow('#ff6b3d'), -26, -26, 52, 52); ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = '#ff9a5c';
    ctx.beginPath();
    for (let i = 0; i < 20; i++) { const a = (i / 20) * Math.PI * 2, r = i % 2 ? 9 : 16; ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r); }
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#6b1a1a'; ctx.beginPath(); ctx.arc(0, 0, 9, 0, Math.PI * 2); ctx.fill();
    ctx.rotate(-e.x / 14);
    ctx.fillStyle = '#ffe66d'; ctx.beginPath(); ctx.arc(e.dir * 3 - 2, -2, 2, 0, Math.PI * 2); ctx.arc(e.dir * 3 + 3, -2, 2, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();
  void time;
}

export function drawBullet(ctx: CanvasRenderingContext2D, b: Bullet) {
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = '#ff4d6d'; ctx.lineWidth = 4; ctx.lineCap = 'round'; ctx.globalAlpha = 0.6;
  ctx.beginPath(); ctx.moveTo(b.x, b.y); ctx.lineTo(b.x - b.vx * 0.06, b.y - b.vy * 0.06); ctx.stroke();
  ctx.globalAlpha = 1;
  ctx.drawImage(glow('#ff4d6d'), b.x - 14, b.y - 14, 28, 28);
  ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(b.x, b.y, 3, 0, Math.PI * 2); ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
}

// Audio sintetizado con Web Audio: efectos y una música espacial en bucle.
const mtof = (m: number) => 440 * Math.pow(2, (m - 69) / 12);
const LEAD = [76, 0, 79, 83, 0, 81, 79, 0, 76, 0, 74, 76, 0, 71, 0, 0, 72, 0, 76, 79, 0, 81, 83, 0, 84, 0, 83, 79, 0, 76, 0, 0];
const BASS = [40, 40, 47, 40, 36, 36, 43, 36, 38, 38, 45, 38, 35, 35, 42, 47];

class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private music: GainNode | null = null;
  private delay: DelayNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private timer = 0; private step = 0; private nextT = 0;
  muted = false;

  init() {
    if (this.ctx) { void this.ctx.resume(); return; }
    const w = window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext };
    const AC = w.AudioContext || w.webkitAudioContext; if (!AC) return;
    try { this.ctx = new AC(); } catch { return; }
    const c = this.ctx;
    this.master = c.createGain(); this.master.gain.value = this.muted ? 0 : 0.45;
    this.music = c.createGain(); this.music.gain.value = 0.16;
    this.delay = c.createDelay(1); this.delay.delayTime.value = 0.27;
    const fb = c.createGain(); fb.gain.value = 0.35;
    this.delay.connect(fb).connect(this.delay); this.delay.connect(this.master);
    this.master.connect(c.destination); this.music.connect(this.master); this.music.connect(this.delay);
    const b = c.createBuffer(1, c.sampleRate, c.sampleRate), d = b.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    this.noiseBuf = b;
    this.nextT = c.currentTime + 0.1;
    this.timer = window.setInterval(() => this.tick(), 50);
  }
  setMuted(m: boolean) { this.muted = m; if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.45, this.ctx.currentTime, 0.02); }

  private tone(f: number, dur: number, type: OscillatorType, vol: number, f2?: number, at = 0, dest?: AudioNode) {
    const c = this.ctx; if (!c || !this.master) return;
    const t = at || c.currentTime, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(f, t); if (f2) o.frequency.exponentialRampToValueAtTime(Math.max(20, f2), t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(vol, t + 0.008); g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    o.connect(g).connect(dest ?? this.master); o.start(t); o.stop(t + dur + 0.03);
  }
  private noise(dur: number, vol: number, freq: number, f2?: number, type: BiquadFilterType = 'lowpass') {
    const c = this.ctx; if (!c || !this.master || !this.noiseBuf) return;
    const t = c.currentTime, s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
    s.buffer = this.noiseBuf; f.type = type; f.frequency.setValueAtTime(freq, t); if (f2) f.frequency.exponentialRampToValueAtTime(f2, t + dur);
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f).connect(g).connect(this.master); s.start(t); s.stop(t + dur);
  }

  play(name: string) {
    const c = this.ctx; if (!c) return;
    const t = c.currentTime;
    switch (name) {
      case 'jump': this.tone(330, 0.16, 'square', 0.09, 660); break;
      case 'jump2': this.tone(520, 0.2, 'triangle', 0.16, 1040); this.noise(0.15, 0.08, 3000, 800, 'bandpass'); break;
      case 'land': this.noise(0.08, 0.12, 600, 150); break;
      case 'dash': this.noise(0.22, 0.25, 6000, 400, 'bandpass'); this.tone(180, 0.18, 'sawtooth', 0.06, 90); break;
      case 'coin': this.tone(1175, 0.06, 'square', 0.07); this.tone(1760, 0.16, 'square', 0.07, undefined, t + 0.055); break;
      case 'stomp': this.tone(240, 0.14, 'square', 0.16, 60); this.noise(0.12, 0.2, 1800, 200); break;
      case 'kill': this.tone(600, 0.2, 'sawtooth', 0.1, 70); this.noise(0.3, 0.25, 2500, 100); break;
      case 'shoot': this.tone(900, 0.12, 'sawtooth', 0.05, 300); break;
      case 'hurt': this.tone(300, 0.3, 'sawtooth', 0.16, 60); this.noise(0.25, 0.2, 1200, 100); break;
      case 'die': [64, 60, 57, 52].forEach((m, i) => this.tone(mtof(m), 0.2, 'square', 0.12, undefined, t + i * 0.1)); this.noise(0.6, 0.3, 1500, 60); break;
      case 'power': [72, 76, 79, 84, 88].forEach((m, i) => this.tone(mtof(m), 0.14, 'triangle', 0.15, undefined, t + i * 0.06)); break;
      case 'shield': this.tone(400, 0.3, 'sine', 0.2, 120); this.noise(0.3, 0.15, 4000, 300, 'bandpass'); break;
      case 'check': [67, 74, 79].forEach((m, i) => this.tone(mtof(m), 0.25, 'triangle', 0.16, undefined, t + i * 0.09)); break;
      case 'portal': [60, 64, 67, 72, 76, 79, 84].forEach((m, i) => this.tone(mtof(m), 0.3, 'square', 0.08, undefined, t + i * 0.07)); break;
      case 'over': [67, 63, 60, 55, 48].forEach((m, i) => this.tone(mtof(m), 0.35, 'triangle', 0.18, undefined, t + i * 0.18)); break;
    }
  }

  private tick() {
    const c = this.ctx; if (!c || !this.music) return;
    const spb = 60 / 128 / 2;
    while (this.nextT < c.currentTime + 0.2) {
      const s = this.step, n = LEAD[s % LEAD.length];
      if (n) this.tone(mtof(n), spb * 1.6, 'triangle', 0.32, undefined, this.nextT, this.music);
      if (s % 2 === 0) this.tone(mtof(BASS[(s >> 1) % BASS.length]), spb * 1.8, 'sawtooth', 0.22, undefined, this.nextT, this.music);
      if (s % 8 === 4) this.tone(mtof(BASS[(s >> 1) % BASS.length] + 24), spb * 6, 'sine', 0.12, undefined, this.nextT, this.music);
      this.nextT += spb; this.step++;
    }
  }

  dispose() {
    window.clearInterval(this.timer);
    if (this.ctx) void this.ctx.close();
    this.ctx = null; this.master = null; this.music = null; this.delay = null;
  }
}

export const audio = new Sfx();

// Motor principal: bucle, cámara, estados de partida, interacciones y progresión de sectores.
import { DIFFS, TS, VIEW_H } from './types';
import type { Bullet, DiffCfg, DiffKey, EndStats, HudState, Level, Player, PowerKind } from './types';
import { generateLevel } from './level';
import { buildTiles, Particles } from './sprites';
import type { TileSet } from './sprites';
import { ENEMY_PTS, newPlayer, overlap, stompable, touchesSpike, updateEnemies, updateMovers, updatePlayer } from './physics';
import type { Fx } from './physics';
import { Background, renderFrame } from './render';
import { audio } from './audio';
import type { Input } from './input';

export interface Callbacks { onHud: (h: HudState) => void; onEnd: (s: EndStats) => void }
const HI_KEY = 'salto-estelar-record';
const POWER_TXT: Record<PowerKind, string> = { shield: '¡ESCUDO!', magnet: '¡IMÁN!', boost: '¡PROPULSOR!', life: '+1 VIDA' };

export class Game {
  private ctx: CanvasRenderingContext2D;
  private vw = 800; private vh = 600; private dpr = 1; private scale = 1;
  private diff: DiffCfg = DIFFS.normal;
  private seed = Math.floor(Math.random() * 1e6);
  level!: Level; private tiles!: TileSet; player!: Player;
  private bullets: Bullet[] = [];
  private particles = new Particles();
  private bg = new Background();
  private cam = { x: 0, y: 0, look: 0 };
  private shake = 0; private flash = 0; private hitstop = 0; private time = 0;
  private banner: { title: string; sub: string; t: number } | null = null;
  mode: 'attract' | 'play' = 'attract';
  paused = false;
  private state: 'run' | 'dead' | 'clear' | 'over' = 'run';
  private stateT = 0;
  private score = 0; private coins = 0; private lives = 3; private kills = 0; private playTime = 0; private levelTime = 0;
  private respawn = { x: 0, y: 0 };
  private raf = 0; private last = 0; private hudT = 0;
  hi = 0;

  constructor(private canvas: HTMLCanvasElement, private input: Input, private cb: Callbacks) {
    this.ctx = canvas.getContext('2d')!;
    try { this.hi = Number(localStorage.getItem(HI_KEY)) || 0; } catch { this.hi = 0; }
    this.loadLevel(0, false);
  }

  resize(w: number, h: number) {
    this.vw = Math.max(1, w); this.vh = Math.max(1, h);
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(this.vw * this.dpr); this.canvas.height = Math.round(this.vh * this.dpr);
    this.scale = this.vh / VIEW_H;
    if (this.vw / this.scale < 560) this.scale = this.vw / 560;
  }

  start(d: DiffKey) {
    this.diff = DIFFS[d];
    this.seed = Math.floor(Math.random() * 1e6);
    this.score = 0; this.coins = 0; this.kills = 0; this.playTime = 0; this.lives = this.diff.lives;
    this.mode = 'play'; this.paused = false;
    this.input.clear();
    this.loadLevel(0, true);
  }

  toAttract() { this.mode = 'attract'; this.paused = false; this.loadLevel(this.level.index, false); }

  private loadLevel(i: number, banner: boolean) {
    this.level = generateLevel(i, this.diff, this.seed);
    this.tiles = buildTiles(this.level.palette);
    this.bg.setPalette(this.level.palette);
    const s = this.level.spawn;
    this.player = newPlayer(s.x, s.y);
    this.respawn = { ...s };
    this.bullets = []; this.particles.clear();
    this.state = 'run'; this.stateT = 0; this.levelTime = 0;
    this.banner = banner ? { title: `SECTOR ${i + 1}`, sub: this.level.name, t: 3 } : null;
    this.cam.x = 0; this.cam.y = this.level.h * TS - VIEW_H;
    this.emitHud();
  }

  run() {
    const loop = (t: number) => {
      this.raf = requestAnimationFrame(loop);
      const dt = Math.min(0.05, Math.max(0, (t - (this.last || t)) / 1000));
      this.last = t;
      if (!this.paused) this.update(dt);
      this.draw();
    };
    this.raf = requestAnimationFrame(loop);
  }
  destroy() { cancelAnimationFrame(this.raf); this.particles.clear(); }

  private get ww() { return this.vw / this.scale; }
  private get wh() { return this.vh / this.scale; }

  private fx: Fx = {
    jump: dbl => {
      const p = this.player, x = p.x + p.w / 2, y = p.y + p.h;
      if (dbl) { audio.play('jump2'); this.particles.ring(x, y, '#ffd23f', 30, 0.35); this.particles.burst(x, y, 10, '#ffb347', 200, 2, 300); }
      else { audio.play('jump'); this.particles.dust(x, y, 6); }
    },
    land: k => { if (k > 0.25) { audio.play('land'); this.particles.dust(this.player.x + this.player.w / 2, this.player.y + this.player.h, Math.round(4 + k * 8)); } if (k > 0.8) this.shake = Math.max(this.shake, 3); },
    dash: () => { audio.play('dash'); this.shake = Math.max(this.shake, 4); const p = this.player; this.particles.ring(p.x + p.w / 2, p.y + p.h / 2, '#7cf7ff', 36, 0.3); },
    bonk: () => audio.play('land'),
  };

  private update(dt: number) {
    this.time += dt;
    this.particles.update(dt);
    this.shake = Math.max(0, this.shake - dt * 30);
    this.flash = Math.max(0, this.flash - dt * 2);
    if (this.banner) { this.banner.t -= dt; if (this.banner.t <= 0) this.banner = null; }
    const l = this.level, p = this.player;
    if (this.mode === 'attract') {
      updateMovers(l.movers, dt);
      updateEnemies(l, { ...p, x: -9999, y: -9999 }, this.bullets, dt, this.diff, () => {});
      this.cam.x += 70 * dt;
      if (this.cam.x > l.w * TS - this.ww) this.cam.x = 0;
      this.cam.y = Math.min(l.h * TS - this.wh, 2 * TS);
      return;
    }
    if (this.hitstop > 0) { this.hitstop -= dt; return; }
    updateMovers(l.movers, dt);
    updateEnemies(l, p, this.bullets, dt, this.diff, () => audio.play('shoot'));
    if (this.state === 'run') {
      updatePlayer(p, l, this.input, dt, this.fx);
      this.playTime += dt; this.levelTime += dt;
      p.magnet = Math.max(0, p.magnet - dt); p.boost = Math.max(0, p.boost - dt);
      this.interact(dt);
    } else if (this.state === 'dead') {
      this.stateT += dt;
      if (this.stateT > 1.2) {
        if (this.lives <= 0) this.gameOver();
        else {
          this.player = newPlayer(this.respawn.x, this.respawn.y);
          this.player.invuln = 1.6; this.bullets = []; this.state = 'run';
          this.particles.ring(this.respawn.x + 10, this.respawn.y + 15, '#7cf7ff', 60, 0.6);
          audio.play('check');
        }
      }
    } else if (this.state === 'clear') {
      this.stateT += dt;
      const tx = l.portal.x - p.w / 2, ty = l.portal.y - 56 - p.h / 2;
      p.x += (tx - p.x) * Math.min(1, dt * 4); p.y += (ty - p.y) * Math.min(1, dt * 4);
      p.sx = p.sy = Math.max(0.01, 1 - this.stateT * 0.8);
      if (Math.random() < 0.6) this.particles.burst(l.portal.x, l.portal.y - 56, 2, l.palette.edge, 220, 2, 0);
      if (this.stateT > 2.4) this.loadLevel(l.index + 1, true);
    }
    this.updateCamera(dt);
    this.hudT -= dt;
    if (this.hudT <= 0) { this.hudT = 0.1; this.emitHud(); }
  }

  private interact(dt: number) {
    const l = this.level, p = this.player, P = this.particles;
    const pcx = p.x + p.w / 2, pcy = p.y + p.h / 2;
    if (p.y > l.h * TS + 120) { this.kill(); return; }
    if (touchesSpike(p, l)) this.hurt();
    for (const c of l.coins) {
      if (c.taken) continue;
      const dx = pcx - c.x, dy = pcy - c.y, d = Math.hypot(dx, dy);
      if (p.magnet > 0 && d < 190) { const k = Math.min(1, dt * 7); c.x += dx * k; c.y += dy * k; }
      if (d < 22) {
        c.taken = true; this.coins++; this.score += 10; audio.play('coin');
        P.burst(c.x, c.y, 6, l.palette.accent, 160, 2, 0); P.ring(c.x, c.y, l.palette.accent, 20, 0.25);
      }
    }
    for (const pw of l.powers) {
      if (pw.taken || Math.hypot(pcx - pw.x, pcy - pw.y) > 28) continue;
      pw.taken = true; this.score += 50; audio.play(pw.kind === 'shield' ? 'shield' : 'power');
      if (pw.kind === 'shield') p.shield = true;
      else if (pw.kind === 'magnet') p.magnet = 12;
      else if (pw.kind === 'boost') { p.boost = 10; p.airJumps = 2; }
      else this.lives++;
      P.ring(pw.x, pw.y, '#ffffff', 60, 0.5); P.burst(pw.x, pw.y, 22, '#ffe66d', 300, 3, 0); P.text(pw.x, pw.y - 30, POWER_TXT[pw.kind], '#7cf7ff');
      this.flash = 0.25;
    }
    for (const e of l.enemies) {
      if (!e.alive || !overlap(p.x, p.y, p.w, p.h, e.x + 3, e.y + 3, e.w - 6, e.h - 4)) continue;
      const ex = e.x + e.w / 2, ey = e.y + e.h / 2;
      if (p.dashT > 0 || (p.invuln > 0 && p.shield)) this.killEnemy(e, ex, ey, false);
      else if (stompable(e) && p.vy > 0 && p.y + p.h - e.y < 18 + p.vy * dt) {
        this.killEnemy(e, ex, ey, true);
        p.vy = this.input.jumpHeld() ? -720 : -520; p.airJumps = p.boost > 0 ? 2 : 1; p.canDash = true; p.sx = 0.75; p.sy = 1.3;
      } else this.hurt();
    }
    for (let i = this.bullets.length - 1; i >= 0; i--) {
      const b = this.bullets[i];
      if (!overlap(p.x, p.y, p.w, p.h, b.x - 5, b.y - 5, 10, 10)) continue;
      this.bullets.splice(i, 1);
      if (p.dashT > 0) { P.burst(b.x, b.y, 10, '#ff4d6d', 220, 2, 0); this.score += 25; } else this.hurt();
    }
    for (const cp of l.checkpoints) {
      if (cp.active || Math.abs(pcx - cp.x) > 26 || Math.abs(p.y + p.h - cp.y) > 80) continue;
      cp.active = true; this.respawn = { x: cp.x - 10, y: cp.y - 32 }; this.score += 50; audio.play('check');
      P.ring(cp.x, cp.y - 66, '#7cf7ff', 70, 0.6); P.burst(cp.x, cp.y - 66, 18, '#7cf7ff', 260, 2, 200); P.text(cp.x, cp.y - 90, 'PUNTO DE CONTROL', '#7cf7ff');
    }
    if (Math.hypot(pcx - l.portal.x, pcy - (l.portal.y - 56)) < 52) {
      const bonus = Math.max(0, Math.round(3000 - this.levelTime * 25));
      this.score += bonus + 500; this.state = 'clear'; this.stateT = 0; this.flash = 0.6; this.shake = 6;
      audio.play('portal');
      this.banner = { title: '¡SECTOR COMPLETADO!', sub: `+500 · bonus de tiempo +${bonus}`, t: 2.6 };
    }
  }

  private killEnemy(e: Level['enemies'][number], x: number, y: number, stomp: boolean) {
    e.alive = false; this.kills++;
    const pts = ENEMY_PTS[e.kind] * (stomp ? 1 : 1.5);
    this.score += pts; this.hitstop = 0.05; this.shake = Math.max(this.shake, 6);
    audio.play(stomp ? 'stomp' : 'kill');
    const col = e.kind === 'crawler' ? '#9dff6a' : e.kind === 'floater' ? '#ff5ea8' : e.kind === 'turret' ? '#ff4d6d' : '#ff9a5c';
    this.particles.burst(x, y, 24, col, 340, 3, 600); this.particles.ring(x, y, col, 46, 0.4);
    this.particles.text(x, y - 24, `+${pts}`);
  }

  private hurt() {
    const p = this.player;
    if (p.invuln > 0 || p.dashT > 0 || this.state !== 'run') return;
    if (p.shield) {
      p.shield = false; p.invuln = 1.2; p.vy = -420; audio.play('shield');
      this.shake = 8; this.particles.burst(p.x + p.w / 2, p.y + p.h / 2, 26, '#5ee7ff', 320, 3, 0);
      return;
    }
    this.kill();
  }

  private kill() {
    const p = this.player;
    if (this.state !== 'run') return;
    p.dead = true; this.state = 'dead'; this.stateT = 0; this.lives--;
    this.shake = 14; this.flash = 0.45; this.hitstop = 0.08;
    audio.play('die');
    const x = p.x + p.w / 2, y = Math.min(p.y + p.h / 2, this.level.h * TS);
    this.particles.burst(x, y, 40, '#ffffff', 420, 3, 300); this.particles.burst(x, y, 20, '#ff8a3d', 300, 4, 300);
    this.particles.ring(x, y, '#ff5d73', 80, 0.6);
  }

  private gameOver() {
    this.state = 'over';
    const rec = this.score > this.hi;
    if (rec) { this.hi = this.score; try { localStorage.setItem(HI_KEY, String(this.hi)); } catch { /* sin almacenamiento */ } }
    audio.play('over');
    this.emitHud();
    this.cb.onEnd({ score: this.score, coins: this.coins, level: this.level.index + 1, enemies: this.kills, time: this.playTime, hi: this.hi, newRecord: rec });
  }

  private updateCamera(dt: number) {
    const p = this.player, l = this.level, ww = this.ww, wh = this.wh;
    this.cam.look += (p.face * ww * 0.12 - this.cam.look) * Math.min(1, dt * 2.5);
    let tx = p.x + p.w / 2 - ww / 2 + this.cam.look;
    let ty = p.y + p.h / 2 - wh * 0.55;
    tx = Math.max(0, Math.min(l.w * TS - ww, tx));
    const maxY = l.h * TS - wh;
    ty = maxY <= 0 ? maxY : Math.max(0, Math.min(maxY, ty));
    this.cam.x += (tx - this.cam.x) * Math.min(1, dt * 7);
    this.cam.y += (ty - this.cam.y) * Math.min(1, dt * 4);
  }

  private emitHud() {
    const p = this.player, l = this.level;
    this.cb.onHud({
      score: Math.round(this.score), coins: this.coins, totalCoins: l.totalCoins, lives: Math.max(0, this.lives), level: l.index + 1, sector: l.name,
      time: this.playTime, shield: p.shield, magnet: p.magnet, boost: p.boost, dashReady: p.canDash && p.dashCd <= 0,
      progress: Math.max(0, Math.min(1, p.x / l.portal.x)),
    });
  }

  private draw() {
    renderFrame(this.ctx, { camX: this.cam.x, camY: this.cam.y, vw: this.vw, vh: this.vh, scale: this.scale, dpr: this.dpr, shake: this.shake }, {
      level: this.level, tiles: this.tiles, player: this.player, bullets: this.bullets, particles: this.particles, bg: this.bg,
      time: this.time, flash: this.flash, showPlayer: this.mode === 'play', banner: this.banner,
    });
  }
}

// Teclado (en window) + botones táctiles. Las acciones "pulsadas" se guardan hasta que el motor las consume.
const BLOCK = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space']);
const JUMP = new Set(['Space', 'ArrowUp', 'KeyW', 'KeyZ', 'KeyK']);
const DASH = new Set(['ShiftLeft', 'ShiftRight', 'KeyX', 'KeyJ', 'KeyC']);

export class Input {
  keys = new Set<string>();
  touch = { left: false, right: false, down: false, jump: false };
  private req = new Set<string>();

  private onDown = (e: KeyboardEvent) => {
    if (BLOCK.has(e.code)) e.preventDefault();
    if (!e.repeat) {
      if (JUMP.has(e.code)) this.req.add('jump');
      if (DASH.has(e.code)) this.req.add('dash');
    }
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  attach() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }
  detach() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }

  press(a: 'jump' | 'dash') { this.req.add(a); }
  take(a: 'jump' | 'dash') { const r = this.req.has(a); this.req.delete(a); return r; }
  clear() { this.req.clear(); this.keys.clear(); this.touch = { left: false, right: false, down: false, jump: false }; }

  jumpHeld() {
    if (this.touch.jump) return true;
    for (const k of JUMP) if (this.keys.has(k)) return true;
    return false;
  }
  axisX() {
    let x = 0;
    if (this.keys.has('ArrowLeft') || this.keys.has('KeyA') || this.touch.left) x -= 1;
    if (this.keys.has('ArrowRight') || this.keys.has('KeyD') || this.touch.right) x += 1;
    return x;
  }
  up() { return this.keys.has('ArrowUp') || this.keys.has('KeyW'); }
  down() { return this.keys.has('ArrowDown') || this.keys.has('KeyS') || this.touch.down; }
}

// Generación procedural de sectores: tramos encadenados de asteroides, abismos, plataformas y enemigos.
import { ROWS, TS } from './types';
import type { Coin, DiffCfg, Enemy, EnemyKind, Level, Mover, Palette, Power, PowerKind } from './types';

export const T_EMPTY = 0, T_ROCK = 1, T_ONEWAY = 2, T_SPIKE = 3;

export function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const PALETTES: Palette[] = [
  { name: 'Nebulosa Violeta', sky0: '#07031a', sky1: '#24104a', nebA: '#7b2cbf', nebB: '#ff4d9d', rock: '#3a2a6b', rockDark: '#1c1440', edge: '#7cf7ff', accent: '#ffd23f', planet: '#ff8a5c' },
  { name: 'Cinturón Esmeralda', sky0: '#020d14', sky1: '#08343a', nebA: '#00b48a', nebB: '#3f8cff', rock: '#1f4a4f', rockDark: '#0c2427', edge: '#9dff6a', accent: '#ffe66d', planet: '#b48cff' },
  { name: 'Corona Solar', sky0: '#140405', sky1: '#4a1320', nebA: '#ff5e3a', nebB: '#ffb347', rock: '#55262c', rockDark: '#2a1015', edge: '#ffd166', accent: '#7cf7ff', planet: '#ffcf70' },
  { name: 'Abismo Glacial', sky0: '#030614', sky1: '#0e2350', nebA: '#2d7dff', nebB: '#a1f0ff', rock: '#2a3c6e', rockDark: '#121c3a', edge: '#c7f9ff', accent: '#ff7bd5', planet: '#7de2ff' },
];

const SECTORS = ['Orión', 'Vega', 'Altair', 'Sirio', 'Rigel', 'Deneb', 'Antares', 'Polaris', 'Cástor', 'Lyra'];

export function generateLevel(index: number, diff: DiffCfg, seed: number): Level {
  const r = rng(seed * 9973 + index * 7919 + 17);
  const ri = (a: number, b: number) => a + Math.floor(r() * (b - a + 1));
  const H = ROWS;
  const W = Math.min(330, 150 + index * 28);
  const tiles = new Uint8Array(W * H);
  const coins: Coin[] = [], powers: Power[] = [], enemies: Enemy[] = [], movers: Mover[] = [];
  const checkpoints: Level['checkpoints'] = [];
  const set = (c: number, row: number, v: number) => { if (c >= 0 && c < W && row >= 0 && row < H) tiles[row * W + c] = v; };
  const fill = (c: number, top: number) => { for (let row = top; row < H; row++) set(c, row, T_ROCK); };
  const coin = (cx: number, cy: number) => coins.push({ x: cx, y: cy, taken: false, t: r() * 6 });
  const power = (cx: number, cy: number, k?: PowerKind) => {
    const kinds: PowerKind[] = ['shield', 'magnet', 'boost', 'shield', 'magnet', 'life'];
    powers.push({ x: cx, y: cy, kind: k ?? kinds[ri(0, kinds.length - 1)], taken: false, t: 0 });
  };
  const enemy = (kind: EnemyKind, x: number, y: number, x0: number, x1: number) => {
    const size: Record<EnemyKind, [number, number]> = { crawler: [28, 22], floater: [30, 26], turret: [30, 28], spiker: [28, 24] };
    const [w, h] = size[kind];
    const sp = (kind === 'spiker' ? 70 : kind === 'crawler' ? 85 : 60) * diff.enemySpeed * (1 + index * 0.06);
    enemies.push({ kind, x, y: y - (kind === 'floater' ? h / 2 : h), w, h, vx: sp, dir: r() < 0.5 ? -1 : 1, x0, x1, baseY: y - h / 2, t: r() * 6, cool: 1 + r() * 2, alive: true, flash: 0 });
  };
  const arc = (c0: number, len: number, top: number, n: number, lift = 2.6) => {
    for (let i = 0; i < n; i++) {
      const k = n === 1 ? 0.5 : i / (n - 1);
      coin((c0 + k * len) * TS, top * TS - TS * 1.2 - Math.sin(k * Math.PI) * TS * lift);
    }
  };
  const dens = diff.density + Math.min(0.35, index * 0.05);

  let c = 0, gy = 12, nextCp = 46;
  for (; c < 12; c++) fill(c, gy);
  const spawn = { x: 3 * TS, y: gy * TS - 30 };
  // acción inmediata: monedas, un blob y una cápsula cerca del inicio
  for (let i = 0; i < 4; i++) coin((6 + i * 1.3) * TS, (gy - 2) * TS);
  enemy('crawler', 9 * TS, gy * TS, 7 * TS, 11.2 * TS);
  power(14 * TS, (gy - 4) * TS, 'shield');

  const flat = (len: number, deco = true) => {
    const s = c;
    for (let i = 0; i < len; i++, c++) fill(c, gy);
    if (c >= nextCp && len >= 5) { checkpoints.push({ x: (s + 2) * TS, y: gy * TS, active: false, t: 0 }); nextCp += 46; return; }
    if (!deco) return;
    if (r() < dens && len >= 5) enemy(index > 0 && r() < 0.35 ? 'spiker' : 'crawler', (s + len / 2) * TS, gy * TS, (s + 0.2) * TS, (s + len - 0.2) * TS);
    else if (r() < 0.6) for (let i = 0; i < Math.min(5, len - 2); i++) coin((s + 1.5 + i) * TS, (gy - 1.6) * TS);
  };

  while (c < W - 18) {
    const k = r();
    if (k < 0.16) { // abismo simple
      flat(ri(3, 6));
      const g = Math.min(5, ri(2, 3) + Math.round(r() * (diff.gap + index * 0.25)));
      arc(c - 0.5, g + 1, gy, 4);
      c += g; flat(ri(3, 5), false);
    } else if (k < 0.3) { // escalón
      gy = Math.max(8, Math.min(14, gy + [-2, -1, 1, 2][ri(0, 3)]));
      flat(ri(5, 8));
    } else if (k < 0.42) { // pinchos
      const s = c; flat(ri(8, 10), false);
      const p = s + ri(3, 4); for (let i = 0; i < ri(2, 3); i++) set(p + i, gy - 1, 3);
      arc(p - 0.5, 3, gy - 1, 3, 2.2);
    } else if (k < 0.56) { // islas flotantes sobre el vacío
      flat(3, false);
      const n = ri(2, 3);
      for (let i = 0; i < n; i++) {
        const px = c + 1 + i * 5, row = gy - ri(1, 3);
        for (let j = 0; j < 3; j++) set(px + j, row, T_ONEWAY);
        coin((px + 1.5) * TS, (row - 1) * TS);
        if (i === 1 && r() < dens) enemy('floater', (px + 1.5) * TS, (row - 3) * TS, (px - 2) * TS, (px + 5) * TS);
        if (r() < 0.12) power((px + 1.5) * TS, (row - 2.5) * TS);
      }
      c += n * 5 + 1; flat(3, false);
    } else if (k < 0.68) { // plataforma móvil
      flat(3, false);
      const L = ri(7, 9), vertical = index > 0 && gy >= 11 && r() < 0.4;
      const m: Mover = { x: 0, y: 0, w: 3 * TS, h: 14, x0: (c + 0.2) * TS, y0: gy * TS, ax: vertical ? 0 : (L - 3.4) * TS, ay: vertical ? -3 * TS : 0, speed: 0.9 + r() * 0.5 + index * 0.05, t: r() * 3, dx: 0, dy: 0 };
      if (vertical) m.x0 = (c + (L - 3) / 2) * TS;
      movers.push(m);
      arc(c, L, gy, 5, 1.6);
      c += L;
      if (vertical) gy -= 3;
      flat(3, false);
    } else if (k < 0.78) { // torreta sobre bloque
      const s = c; flat(9, false);
      const b = s + 4; for (let j = 0; j < 2; j++) { set(b, gy - 1 - j, T_ROCK); set(b + 1, gy - 1 - j, T_ROCK); }
      enemy('turret', (b + 1) * TS - 15, (gy - 2) * TS, 0, 0);
      for (let i = 0; i < 3; i++) coin((b + 0.5 + i * 0.5) * TS, (gy - 5) * TS);
    } else if (k < 0.88) { // pilares
      flat(2, false);
      for (let i = 0; i < 3; i++) {
        c += ri(2, 2 + Math.round(diff.gap));
        const top = Math.max(8, Math.min(14, gy + ri(-2, 1))), wid = ri(1, 2);
        for (let j = 0; j < wid; j++, c++) fill(c, top);
        coin((c - wid / 2) * TS, (top - 1.5) * TS);
        gy = top;
      }
      c += 2; flat(4, false);
    } else { // campo de medusas
      const s = c; flat(ri(10, 12), false);
      for (let i = 0; i < 2; i++) if (r() < dens + 0.2) enemy('floater', (s + 3 + i * 5) * TS, (gy - 3 - i) * TS, (s + 1 + i * 5) * TS, (s + 6 + i * 5) * TS);
      for (let i = 0; i < 6; i++) coin((s + 2 + i * 1.4) * TS, (gy - 1.6) * TS);
      if (r() < 0.25) power((s + 6) * TS, (gy - 5) * TS);
    }
  }
  for (; c < W; c++) fill(c, gy);
  const pal = PALETTES[index % PALETTES.length];
  return {
    index, name: `Sector ${SECTORS[index % SECTORS.length]} · ${pal.name}`, w: W, h: H, tiles, coins, powers, enemies, movers, checkpoints,
    portal: { x: (W - 7) * TS, y: gy * TS }, spawn, palette: pal, totalCoins: coins.length,
  };
}

export function tileAt(l: Level, c: number, row: number) {
  if (c < 0 || c >= l.w) return T_ROCK;
  if (row < 0 || row >= l.h) return T_EMPTY;
  return l.tiles[row * l.w + c];
}

// Física del astronauta: carrera con inercia, coyote time, buffer de salto, salto variable, doble salto,
// dash en 8 direcciones, plataformas de un sentido y móviles, squash & stretch.
import { TS } from './types';
import type { Bullet, DiffCfg, Enemy, Level, Mover, Player } from './types';
import { T_ONEWAY, T_ROCK, T_SPIKE, tileAt } from './level';
import type { Input } from './input';

export const PHYS = {
  run: 290, accG: 2600, accA: 1750, fric: 2900, grav: 2300, jump: 740, jump2: 660, maxFall: 950,
  coyote: 0.1, buffer: 0.13, dashSpd: 800, dashT: 0.15, dashCd: 0.28,
};

export interface Fx { jump(double: boolean): void; land(impact: number): void; dash(): void; bonk(): void }

export function newPlayer(x: number, y: number): Player {
  return {
    x, y, w: 20, h: 30, vx: 0, vy: 0, face: 1, onGround: false, coyote: 0, buffer: 0, airJumps: 1, jumpHeld: false,
    dashT: 0, dashCd: 0, canDash: true, dashDir: { x: 1, y: 0 }, sx: 1, sy: 1, invuln: 0, dead: false, deadT: 0,
    riding: null, trail: [], runT: 0, flame: 0, shield: false, magnet: 0, boost: 0,
  };
}

export function updateMovers(movers: Mover[], dt: number) {
  for (const m of movers) {
    m.t += dt;
    const k = 0.5 - 0.5 * Math.cos(m.t * m.speed);
    const nx = m.x0 + m.ax * k, ny = m.y0 + m.ay * k;
    m.dx = m.t > dt ? nx - m.x : 0; m.dy = m.t > dt ? ny - m.y : 0;
    m.x = nx; m.y = ny;
  }
}

function moveX(p: Player, l: Level, dx: number) {
  p.x += dx;
  const top = Math.floor(p.y / TS), bot = Math.floor((p.y + p.h - 0.01) / TS);
  if (dx > 0) {
    const c = Math.floor((p.x + p.w) / TS);
    for (let r = top; r <= bot; r++) if (tileAt(l, c, r) === T_ROCK) { p.x = c * TS - p.w; if (p.dashT <= 0) p.vx = 0; return; }
  } else if (dx < 0) {
    const c = Math.floor(p.x / TS);
    for (let r = top; r <= bot; r++) if (tileAt(l, c, r) === T_ROCK) { p.x = (c + 1) * TS; if (p.dashT <= 0) p.vx = 0; return; }
  }
}

/** Devuelve 1 si aterrizó, -1 si chocó con el techo, 0 si nada. */
function moveY(p: Player, l: Level, dy: number, drop: boolean): number {
  const prevBottom = p.y + p.h;
  p.y += dy;
  const c0 = Math.floor(p.x / TS), c1 = Math.floor((p.x + p.w - 0.01) / TS);
  if (dy > 0) {
    const r = Math.floor((p.y + p.h) / TS);
    for (let c = c0; c <= c1; c++) {
      const t = tileAt(l, c, r);
      if (t === T_ROCK || (t === T_ONEWAY && !drop && prevBottom <= r * TS + 0.5)) { p.y = r * TS - p.h; return 1; }
    }
  } else if (dy < 0) {
    const r = Math.floor(p.y / TS);
    for (let c = c0; c <= c1; c++) if (tileAt(l, c, r) === T_ROCK) { p.y = (r + 1) * TS; return -1; }
  }
  return 0;
}

export function updatePlayer(p: Player, l: Level, inp: Input, dt: number, fx: Fx) {
  const ax = inp.axisX(), held = inp.jumpHeld(), drop = inp.down();
  const run = PHYS.run * (p.boost > 0 ? 1.22 : 1);
  if (inp.take('jump')) p.buffer = PHYS.buffer; else p.buffer = Math.max(0, p.buffer - dt);
  p.coyote = p.onGround ? PHYS.coyote : Math.max(0, p.coyote - dt);
  p.dashCd = Math.max(0, p.dashCd - dt);
  p.invuln = Math.max(0, p.invuln - dt);
  p.flame = Math.max(0, p.flame - dt * 3);
  if (ax) p.face = ax;

  // dash
  if (inp.take('dash') && p.canDash && p.dashCd <= 0 && p.dashT <= 0) {
    let dx = ax, dy = inp.up() ? -1 : drop && !p.onGround ? 1 : 0;
    if (!dx && !dy) dx = p.face;
    const m = Math.hypot(dx, dy); p.dashDir = { x: dx / m, y: dy / m };
    p.dashT = PHYS.dashT; p.canDash = false; p.dashCd = PHYS.dashCd; p.flame = 1;
    p.sx = 1.35; p.sy = 0.75; fx.dash();
  }

  if (p.dashT > 0) {
    p.dashT -= dt;
    p.vx = p.dashDir.x * PHYS.dashSpd; p.vy = p.dashDir.y * PHYS.dashSpd;
    if (p.dashT <= 0) { p.vx *= 0.55; p.vy *= 0.35; }
  } else {
    const acc = p.onGround ? PHYS.accG : PHYS.accA;
    if (ax) {
      const turning = Math.sign(p.vx) !== ax && p.vx !== 0;
      p.vx += ax * acc * (turning ? 1.6 : 1) * dt;
      if (Math.abs(p.vx) > run) p.vx = Math.sign(p.vx) * Math.max(run, Math.abs(p.vx) - PHYS.fric * dt);
    } else {
      const f = (p.onGround ? PHYS.fric : PHYS.fric * 0.35) * dt;
      p.vx = Math.abs(p.vx) <= f ? 0 : p.vx - Math.sign(p.vx) * f;
    }
    // gravedad con salto variable y "flotación" en el ápice
    let g = PHYS.grav;
    if (p.vy < 0 && !held) g *= 2.4;
    else if (p.vy > 0) g *= 1.25;
    if (Math.abs(p.vy) < 90 && held) g *= 0.55;
    p.vy = Math.min(PHYS.maxFall, p.vy + g * dt);

    // salto (con coyote time y buffer)
    if (p.buffer > 0) {
      if (p.coyote > 0) {
        p.vy = -PHYS.jump; p.coyote = 0; p.buffer = 0; p.onGround = false; p.riding = null;
        p.sx = 0.7; p.sy = 1.32; fx.jump(false);
      } else if (p.airJumps > 0) {
        p.vy = -PHYS.jump2; p.airJumps--; p.buffer = 0; p.flame = 1;
        p.sx = 0.75; p.sy = 1.28; fx.jump(true);
      }
    }
  }

  // plataforma móvil sobre la que va montado
  if (p.riding) { p.x += p.riding.dx; p.y += p.riding.dy; }
  const prevBottom = p.y + p.h, fallV = p.vy;
  const steps = Math.max(1, Math.ceil((Math.max(Math.abs(p.vx), Math.abs(p.vy)) * dt) / 10));
  let landed = false;
  for (let i = 0; i < steps; i++) {
    moveX(p, l, (p.vx * dt) / steps);
    const r = moveY(p, l, (p.vy * dt) / steps, drop);
    if (r === 1) { landed = true; p.vy = 0; }
    if (r === -1) { if (p.vy < -200) fx.bonk(); p.vy = 0; }
  }
  let ride: Mover | null = null;
  if (p.vy >= 0) for (const m of l.movers) {
    if (p.x + p.w > m.x + 2 && p.x < m.x + m.w - 2 && prevBottom <= m.y + 6 && p.y + p.h >= m.y - 0.5) {
      p.y = m.y - p.h; p.vy = 0; landed = true; ride = m; break;
    }
  }
  p.riding = ride;
  const was = p.onGround;
  p.onGround = landed;
  if (landed) {
    p.airJumps = p.boost > 0 ? 2 : 1;
    if (p.dashT <= 0) p.canDash = true;
    if (!was) { const k = Math.min(1, fallV / 900); p.sx = 1 + 0.4 * k; p.sy = 1 - 0.35 * k; fx.land(k); }
  }
  if (p.onGround && Math.abs(p.vx) > 20) p.runT += dt * (Math.abs(p.vx) / run);
  // relajar squash & stretch
  const rl = Math.min(1, dt * 14);
  p.sx += (1 - p.sx) * rl; p.sy += (1 - p.sy) * rl;
  // estela
  if (p.dashT > 0 || p.boost > 0 && Math.abs(p.vx) > 200) p.trail.push({ x: p.x + p.w / 2, y: p.y + p.h, face: p.face, a: p.dashT > 0 ? 1 : 0.45 });
  for (const t of p.trail) t.a -= dt * 4;
  while (p.trail.length && p.trail[0].a <= 0) p.trail.shift();
  if (p.trail.length > 10) p.trail.shift();
}

export function touchesSpike(p: Player, l: Level) {
  const c0 = Math.floor((p.x + 3) / TS), c1 = Math.floor((p.x + p.w - 3) / TS);
  const r0 = Math.floor((p.y + 4) / TS), r1 = Math.floor((p.y + p.h - 1) / TS);
  for (let r = r0; r <= r1; r++) for (let c = c0; c <= c1; c++) {
    if (tileAt(l, c, r) === T_SPIKE && p.y + p.h > r * TS + 12) return true;
  }
  return false;
}

// ---------- Enemigos y proyectiles ----------
export function updateEnemies(l: Level, p: Player, bullets: Bullet[], dt: number, diff: DiffCfg, onShoot: (e: Enemy) => void) {
  const px = p.x + p.w / 2, py = p.y + p.h / 2;
  for (const e of l.enemies) {
    if (!e.alive) continue;
    e.t += dt; e.flash = Math.max(0, e.flash - dt);
    if (e.kind === 'crawler' || e.kind === 'spiker') {
      e.x += e.dir * e.vx * dt;
      if (e.x < e.x0) { e.x = e.x0; e.dir = 1; }
      if (e.x + e.w > e.x1) { e.x = e.x1 - e.w; e.dir = -1; }
    } else if (e.kind === 'floater') {
      e.x += e.dir * e.vx * 0.6 * dt;
      if (e.x < e.x0) { e.x = e.x0; e.dir = 1; }
      if (e.x + e.w > e.x1) { e.x = e.x1 - e.w; e.dir = -1; }
      e.y = e.baseY - e.h / 2 + Math.sin(e.t * 2.2) * 26;
    } else {
      e.cool -= dt;
      const dx = px - (e.x + e.w / 2), dy = py - (e.y + 10);
      if (e.cool <= 0 && Math.abs(dx) < 520 && Math.abs(dy) < 320 && !p.dead) {
        const m = Math.hypot(dx, dy) || 1, sp = 250 * diff.fire;
        bullets.push({ x: e.x + e.w / 2 + (dx / m) * 22, y: e.y + 12 + (dy / m) * 22, vx: (dx / m) * sp, vy: (dy / m) * sp, life: 3.5 });
        e.cool = 2.3 / diff.fire; e.flash = 0.2;
        onShoot(e);
      }
    }
  }
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt;
    if (b.life <= 0 || tileAt(l, Math.floor(b.x / TS), Math.floor(b.y / TS)) === T_ROCK) bullets.splice(i, 1);
  }
}

export const overlap = (ax: number, ay: number, aw: number, ah: number, bx: number, by: number, bw: number, bh: number) =>
  ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;

/** Puntuación por tipo de enemigo. */
export const ENEMY_PTS: Record<Enemy['kind'], number> = { crawler: 100, floater: 150, turret: 250, spiker: 200 };
/** Los erizos no se pueden pisar (solo con dash o escudo). */
export const stompable = (e: Enemy) => e.kind !== 'spiker';

// Composición de cada fotograma: fondo parallax, casillas, objetos, actores, partículas y viñeta.
import { TS } from './types';
import type { Bullet, Level, Palette, Player } from './types';
import { T_ONEWAY, T_ROCK, T_SPIKE } from './level';
import { drawCheckpoint, drawCoin, drawMover, drawPortal, drawPower, glow } from './sprites';
import type { Particles, TileSet } from './sprites';
import { drawBullet, drawEnemy, drawPlayer } from './actors';

// ---------- Fondo con parallax: cielo, nebulosa, planeta anillado, estrellas y crestas ----------
interface Star { x: number; y: number; r: number; tw: number }
const mk = (w: number, h: number) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };

export class Background {
  private nebula: HTMLCanvasElement = mk(4, 4);
  private planet: HTMLCanvasElement = mk(4, 4);
  private layers: { f: number; stars: Star[] }[] = [];
  private pal: Palette | null = null;
  private shoot = { x: 0, y: 0, t: -1 };

  constructor() {
    let s = 3;
    const r = () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
    this.layers = [0.04, 0.1, 0.22].map((f, i) => ({
      f, stars: Array.from({ length: [160, 90, 45][i] }, () => ({ x: r(), y: r(), r: (0.6 + r() * 0.9) * (1 + i * 0.6), tw: r() * 6 })),
    }));
  }

  setPalette(p: Palette) {
    if (this.pal === p) return;
    this.pal = p;
    const n = mk(640, 360), g = n.getContext('2d')!;
    let s = 11; const r = () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
    g.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 26; i++) {
      const x = r() * 640, y = 60 + r() * 240, rad = 50 + r() * 150, col = i % 3 === 0 ? p.nebB : p.nebA;
      g.globalAlpha = 0.07 + r() * 0.12; g.drawImage(glow(col), x - rad, y - rad * 0.6, rad * 2, rad * 1.2);
    }
    this.nebula = n;
    const pc = mk(320, 220), q = pc.getContext('2d')!;
    q.translate(160, 110);
    const ring = (front: boolean) => {
      q.save(); q.rotate(-0.35); q.scale(1, 0.26);
      q.strokeStyle = p.planet; q.globalAlpha = 0.55; q.lineWidth = 9;
      q.beginPath(); q.arc(0, 0, 118, front ? 0 : Math.PI, front ? Math.PI : Math.PI * 2); q.stroke();
      q.globalAlpha = 0.3; q.lineWidth = 4; q.beginPath(); q.arc(0, 0, 134, front ? 0 : Math.PI, front ? Math.PI : Math.PI * 2); q.stroke();
      q.restore(); q.globalAlpha = 1;
    };
    ring(false);
    const pg = q.createRadialGradient(-22, -24, 6, 0, 0, 64);
    pg.addColorStop(0, '#ffffff'); pg.addColorStop(0.15, p.planet); pg.addColorStop(1, p.rockDark);
    q.fillStyle = pg; q.beginPath(); q.arc(0, 0, 62, 0, Math.PI * 2); q.fill();
    q.globalAlpha = 0.18; q.fillStyle = p.rockDark;
    for (let i = -3; i <= 3; i++) q.fillRect(-62, i * 15, 124, 6);
    q.globalAlpha = 1;
    ring(true);
    this.planet = pc;
  }

  private ridge(ctx: CanvasRenderingContext2D, vw: number, vh: number, camX: number, scale: number, f: number, base: number, amp: number, col: string, seed: number) {
    const off = camX * f;
    ctx.fillStyle = col; ctx.beginPath(); ctx.moveTo(0, vh);
    for (let sx = 0; sx <= vw + 24; sx += 24) {
      const wx = (sx / scale + off) * 0.01 + seed;
      const h = Math.sin(wx) * 0.5 + Math.sin(wx * 2.3 + 1.7) * 0.3 + Math.sin(wx * 5.1) * 0.12;
      ctx.lineTo(sx, vh * base - h * amp * scale);
    }
    ctx.lineTo(vw + 24, vh); ctx.closePath(); ctx.fill();
  }

  draw(ctx: CanvasRenderingContext2D, camX: number, camY: number, vw: number, vh: number, scale: number, time: number) {
    const p = this.pal; if (!p) return;
    const sky = ctx.createLinearGradient(0, 0, 0, vh);
    sky.addColorStop(0, p.sky0); sky.addColorStop(1, p.sky1);
    ctx.fillStyle = sky; ctx.fillRect(0, 0, vw, vh);
    // nebulosa
    const nw = Math.max(vw, vh * 1.8) * 1.2, nh = nw * 0.5625;
    let nx = -((camX * 0.015 * scale) % nw);
    const ny = vh * 0.5 - nh * 0.5 - camY * 0.01 * scale;
    for (; nx < vw; nx += nw) ctx.drawImage(this.nebula, nx, ny, nw, nh);
    // planeta
    const ps = Math.min(vw, vh) * 0.62;
    ctx.drawImage(this.planet, vw * 0.74 - ps * 0.73 - camX * 0.03 * scale % (vw * 3), vh * 0.3 - ps * 0.34, ps * 1.45, ps);
    // estrellas
    ctx.globalCompositeOperation = 'lighter';
    const T = 1400;
    for (const L of this.layers) {
      const ox = camX * L.f * scale, oy = camY * L.f * scale * 0.5;
      for (const s of L.stars) {
        let x = s.x * T - (ox % T); if (x < 0) x += T;
        let y = (s.y * vh * 1.1 - oy) % vh; if (y < 0) y += vh;
        if (x > vw) continue;
        for (let rx = x; rx < vw; rx += T) {
          const a = 0.55 + Math.sin(time * 2 + s.tw) * 0.45;
          ctx.globalAlpha = a; ctx.fillStyle = '#ffffff';
          ctx.fillRect(rx, y, s.r, s.r);
          if (s.r > 2.2) { ctx.globalAlpha = a * 0.6; ctx.drawImage(glow(p.edge), rx - s.r * 3, y - s.r * 3, s.r * 7, s.r * 7); }
        }
      }
    }
    // estrella fugaz
    if (this.shoot.t < 0 && Math.random() < 0.006) this.shoot = { x: Math.random() * vw, y: Math.random() * vh * 0.4, t: 0 };
    if (this.shoot.t >= 0) {
      const s = this.shoot; s.t += 1 / 60;
      const k = s.t / 0.7, x = s.x + s.t * 900, y = s.y + s.t * 380;
      ctx.globalAlpha = Math.max(0, 1 - k); ctx.strokeStyle = '#ffffff'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 120, y - 50); ctx.stroke();
      if (k >= 1) s.t = -1;
    }
    ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
    // crestas lejanas
    this.ridge(ctx, vw, vh, camX, scale, 0.18, 0.78, 70, p.rockDark + 'aa', 3);
    this.ridge(ctx, vw, vh, camX, scale, 0.35, 0.9, 55, p.rockDark, 9);
    const haze = ctx.createLinearGradient(0, vh * 0.6, 0, vh);
    haze.addColorStop(0, p.nebA + '00'); haze.addColorStop(1, p.nebA + '40');
    ctx.fillStyle = haze; ctx.fillRect(0, vh * 0.6, vw, vh * 0.4);
  }
}

// ---------- Fotograma ----------
export interface View { camX: number; camY: number; vw: number; vh: number; scale: number; dpr: number; shake: number }
export interface Scene {
  level: Level; tiles: TileSet; player: Player; bullets: Bullet[]; particles: Particles; bg: Background;
  time: number; flash: number; showPlayer: boolean; banner: { title: string; sub: string; t: number } | null;
}

export function renderFrame(ctx: CanvasRenderingContext2D, v: View, s: Scene) {
  const { level: l, tiles: T, time } = s;
  const k = v.dpr * v.scale;
  ctx.setTransform(v.dpr, 0, 0, v.dpr, 0, 0);
  s.bg.draw(ctx, v.camX, v.camY, v.vw, v.vh, v.scale, time);
  const sx = (Math.random() - 0.5) * v.shake * 2, sy = (Math.random() - 0.5) * v.shake * 2;
  const cx = v.camX + sx, cy = v.camY + sy;
  ctx.setTransform(k, 0, 0, k, -cx * k, -cy * k);
  const ww = v.vw / v.scale, wh = v.vh / v.scale;
  const c0 = Math.max(0, Math.floor(cx / TS) - 1), c1 = Math.min(l.w - 1, Math.ceil((cx + ww) / TS) + 1);
  const r0 = Math.max(0, Math.floor(cy / TS)), r1 = Math.min(l.h - 1, Math.ceil((cy + wh) / TS));
  const inView = (x: number, pad = 80) => x > cx - pad && x < cx + ww + pad;

  // portal y balizas (detrás de las casillas)
  if (inView(l.portal.x, 160)) drawPortal(ctx, l.portal.x, l.portal.y, time, l.palette);
  for (const cp of l.checkpoints) if (inView(cp.x)) drawCheckpoint(ctx, cp, time);

  // casillas
  const tops: number[] = [], gems: number[] = [];
  for (let r = r0; r <= r1; r++) {
    for (let c = c0; c <= c1; c++) {
      const t = l.tiles[r * l.w + c];
      if (!t) continue;
      const x = c * TS, y = r * TS;
      if (t === T_ROCK) {
        const above = r > 0 ? l.tiles[(r - 1) * l.w + c] : 0;
        const top = above !== T_ROCK;
        ctx.drawImage((top ? T.top : T.body)[(c * 7 + r * 13) % 3], x, y, TS + 0.6, TS + 0.6);
        if (top) tops.push(x, y);
        else {
          let d = 1; while (d < 5 && r - d > 0 && l.tiles[(r - d - 1) * l.w + c] === T_ROCK) d++;
          ctx.fillStyle = `rgba(4,2,16,${Math.min(0.6, d * 0.12)})`; ctx.fillRect(x, y, TS + 0.6, TS + 0.6);
          const h = (c * 73856093) ^ (r * 19349663);
          if ((h & 31) === 7) gems.push(x + 8 + (h >> 5 & 15), y + 8 + (h >> 9 & 15));
        }
        if (c > 0 && l.tiles[r * l.w + c - 1] !== T_ROCK) { ctx.fillStyle = 'rgba(0,0,0,0.3)'; ctx.fillRect(x, y, 4, TS); }
        if (c < l.w - 1 && l.tiles[r * l.w + c + 1] !== T_ROCK) { ctx.fillStyle = 'rgba(255,255,255,0.08)'; ctx.fillRect(x + TS - 3, y, 3, TS); }
      } else if (t === T_ONEWAY) {
        ctx.drawImage(T.oneway, x, y, TS + 0.5, 14);
      } else if (t === T_SPIKE) {
        ctx.drawImage(T.spike, x, y);
      }
    }
  }
  // roca bajo el borde inferior del nivel (si la vista es más alta)
  const bottom = l.h * TS;
  if (cy + wh > bottom) {
    ctx.fillStyle = l.palette.rockDark;
    for (let c = c0; c <= c1; c++) if (l.tiles[(l.h - 1) * l.w + c] === T_ROCK) ctx.fillRect(c * TS, bottom, TS + 0.6, cy + wh - bottom);
  }
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < tops.length; i += 2) ctx.drawImage(T.edgeGlow, tops[i], tops[i + 1] - 20, TS, 20);
  const gc = glow(l.palette.nebB);
  for (let i = 0; i < gems.length; i += 2) {
    const gx = gems[i], gy = gems[i + 1], a = 0.6 + Math.sin(time * 2 + gx) * 0.3;
    ctx.globalAlpha = a; ctx.drawImage(gc, gx - 14, gy - 14, 28, 28);
    ctx.fillStyle = l.palette.nebB; ctx.beginPath(); ctx.moveTo(gx, gy - 6); ctx.lineTo(gx + 3, gy); ctx.lineTo(gx, gy + 6); ctx.lineTo(gx - 3, gy); ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';

  for (const m of l.movers) if (inView(m.x, m.w + 40)) drawMover(ctx, m, l.palette, time);
  for (const cn of l.coins) if (!cn.taken && inView(cn.x)) drawCoin(ctx, cn.x, cn.y, time + cn.t, l.palette.accent);
  for (const pw of l.powers) if (!pw.taken && inView(pw.x)) drawPower(ctx, pw, time);
  const p = s.player;
  for (const e of l.enemies) if (e.alive && inView(e.x)) drawEnemy(ctx, e, time, p.x + p.w / 2, p.y + p.h / 2);
  for (const b of s.bullets) drawBullet(ctx, b);
  if (s.showPlayer) drawPlayer(ctx, p, time);
  s.particles.draw(ctx);

  // capa de pantalla: viñeta, destello y rótulo
  ctx.setTransform(v.dpr, 0, 0, v.dpr, 0, 0);
  const vg = ctx.createRadialGradient(v.vw / 2, v.vh / 2, Math.min(v.vw, v.vh) * 0.35, v.vw / 2, v.vh / 2, Math.max(v.vw, v.vh) * 0.75);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,10,0.55)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, v.vw, v.vh);
  if (s.flash > 0) { ctx.fillStyle = `rgba(255,255,255,${Math.min(0.7, s.flash)})`; ctx.fillRect(0, 0, v.vw, v.vh); }
  if (s.banner && s.banner.t > 0) {
    const b = s.banner, a = Math.min(1, b.t * 2, (3 - b.t) * 4);
    const slide = (1 - Math.min(1, (3 - b.t) * 3)) * 40;
    ctx.globalAlpha = Math.max(0, a);
    ctx.textAlign = 'center';
    const fs = Math.min(64, v.vw / 12);
    ctx.font = `900 italic ${fs}px "Trebuchet MS", "Segoe UI", system-ui, sans-serif`;
    const gy = v.vh * 0.36 + slide;
    const tg = ctx.createLinearGradient(0, gy - fs, 0, gy);
    tg.addColorStop(0, '#ffffff'); tg.addColorStop(1, l.palette.edge);
    ctx.lineWidth = 8; ctx.strokeStyle = 'rgba(8,4,30,0.8)'; ctx.strokeText(b.title, v.vw / 2, gy);
    ctx.fillStyle = tg; ctx.fillText(b.title, v.vw / 2, gy);
    ctx.font = `700 ${Math.max(14, fs * 0.34)}px "Trebuchet MS", system-ui, sans-serif`;
    ctx.lineWidth = 5; ctx.strokeText(b.sub, v.vw / 2, gy + fs * 0.6);
    ctx.fillStyle = l.palette.accent; ctx.fillText(b.sub, v.vw / 2, gy + fs * 0.6);
    ctx.globalAlpha = 1;
  }
}

// Sprites procedurales: brillos, casillas de asteroide y objetos (fragmentos, cápsulas, portal, balizas).
import { TS } from './types';
import type { Checkpoint, Mover, Palette, Power } from './types';

const mk = (w: number, h: number) => { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; };
const glowCache = new Map<string, HTMLCanvasElement>();

/** Degradado radial cacheado por color: base de todos los resplandores aditivos. */
export function glow(color: string) {
  let c = glowCache.get(color);
  if (!c) {
    c = mk(64, 64); const g = c.getContext('2d')!;
    const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    gr.addColorStop(0, color); gr.addColorStop(0.25, color + 'aa'); gr.addColorStop(1, color + '00');
    g.fillStyle = gr; g.fillRect(0, 0, 64, 64); glowCache.set(color, c);
  }
  return c;
}

export interface TileSet { body: HTMLCanvasElement[]; top: HTMLCanvasElement[]; edgeGlow: HTMLCanvasElement; oneway: HTMLCanvasElement; spike: HTMLCanvasElement }

export function buildTiles(p: Palette): TileSet {
  let seed = 7;
  const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
  const body = (top: boolean) => {
    const c = mk(TS, TS), g = c.getContext('2d')!;
    const gr = g.createLinearGradient(0, 0, 0, TS); gr.addColorStop(0, p.rock); gr.addColorStop(1, p.rockDark);
    g.fillStyle = top ? gr : p.rockDark; g.fillRect(0, 0, TS, TS);
    if (!top) { g.fillStyle = p.rock; g.globalAlpha = 0.35; g.fillRect(0, 0, TS, TS); g.globalAlpha = 1; }
    for (let i = 0; i < 3; i++) {
      const x = rnd() * TS, y = (top ? 10 : 0) + rnd() * (TS - (top ? 10 : 0)), r = 2 + rnd() * 4;
      g.fillStyle = 'rgba(0,0,0,0.28)'; g.beginPath(); g.arc(x, y, r, 0, Math.PI * 2); g.fill();
      g.fillStyle = 'rgba(255,255,255,0.08)'; g.beginPath(); g.arc(x - 1, y - 1, r * 0.6, 0, Math.PI * 2); g.fill();
    }
    for (let i = 0; i < 6; i++) { g.fillStyle = `rgba(255,255,255,${0.05 + rnd() * 0.1})`; g.fillRect(rnd() * TS, rnd() * TS, 1.5, 1.5); }
    if (top) {
      g.fillStyle = p.edge; g.globalAlpha = 0.25; g.fillRect(0, 0, TS, 7); g.globalAlpha = 1;
      g.fillStyle = p.edge; g.fillRect(0, 0, TS, 3);
      g.fillStyle = '#ffffff'; g.globalAlpha = 0.7; g.fillRect(0, 0, TS, 1); g.globalAlpha = 1;
      for (let i = 0; i < 2; i++) { // cristalitos
        const x = 4 + rnd() * (TS - 8), h = 3 + rnd() * 5;
        g.fillStyle = p.edge; g.beginPath(); g.moveTo(x - 2, 1); g.lineTo(x, -h + 1); g.lineTo(x + 2, 1); g.fill();
      }
    }
    return c;
  };
  const edgeGlow = mk(TS, 20); { const g = edgeGlow.getContext('2d')!; const gr = g.createLinearGradient(0, 20, 0, 0); gr.addColorStop(0, p.edge + '88'); gr.addColorStop(1, p.edge + '00'); g.fillStyle = gr; g.fillRect(0, 0, TS, 20); }
  const oneway = mk(TS, 14); {
    const g = oneway.getContext('2d')!;
    const gr = g.createLinearGradient(0, 0, 0, 14); gr.addColorStop(0, '#e6ecff'); gr.addColorStop(0.3, '#8a94c8'); gr.addColorStop(1, '#2a2f55');
    g.fillStyle = gr; g.fillRect(0, 0, TS, 12); g.fillStyle = '#11142a'; g.fillRect(0, 12, TS, 2);
    g.fillStyle = p.accent; g.fillRect(4, 8, 6, 2); g.fillRect(22, 8, 6, 2);
    g.fillStyle = 'rgba(0,0,0,0.35)'; g.fillRect(15, 2, 2, 10);
  }
  const spike = mk(TS, TS); {
    const g = spike.getContext('2d')!;
    for (let i = 0; i < 3; i++) {
      const x = i * 11 + 0.5, gr = g.createLinearGradient(0, TS, 0, 8);
      gr.addColorStop(0, '#5a0f2e'); gr.addColorStop(1, '#ff4d8d');
      g.fillStyle = gr; g.beginPath(); g.moveTo(x, TS); g.lineTo(x + 5.5, 8 + (i % 2) * 5); g.lineTo(x + 11, TS); g.fill();
      g.fillStyle = 'rgba(255,255,255,0.6)'; g.beginPath(); g.moveTo(x + 5.5, 9 + (i % 2) * 5); g.lineTo(x + 6.5, TS - 6); g.lineTo(x + 5, TS - 6); g.fill();
    }
  }
  return { body: [body(false), body(false), body(false)], top: [body(true), body(true), body(true)], edgeGlow, oneway, spike };
}

export function drawCoin(ctx: CanvasRenderingContext2D, x: number, y: number, t: number, color: string) {
  const bob = Math.sin(t * 3) * 3, spin = Math.cos(t * 4);
  ctx.globalCompositeOperation = 'lighter';
  ctx.drawImage(glow(color), x - 18, y - 18 + bob, 36, 36);
  ctx.globalCompositeOperation = 'source-over';
  ctx.save(); ctx.translate(x, y + bob); ctx.scale(Math.max(0.15, Math.abs(spin)), 1);
  ctx.fillStyle = color; ctx.beginPath();
  for (let i = 0; i < 8; i++) { const a = (i / 8) * Math.PI * 2 - Math.PI / 2, r = i % 2 ? 3.5 : 9; ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r); }
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(-1.5, -2, 2, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

const POWER_COL: Record<Power['kind'], string> = { shield: '#5ee7ff', magnet: '#ff5ea8', boost: '#9dff6a', life: '#ff4d6d' };
export function drawPower(ctx: CanvasRenderingContext2D, pw: Power, time: number) {
  const x = pw.x, y = pw.y + Math.sin(time * 2.5 + pw.x) * 5, col = POWER_COL[pw.kind];
  ctx.globalCompositeOperation = 'lighter';
  ctx.drawImage(glow(col), x - 34, y - 34, 68, 68);
  ctx.globalCompositeOperation = 'source-over';
  ctx.save(); ctx.translate(x, y);
  ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.rotate(time * 1.5);
  ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI * 1.4); ctx.stroke(); ctx.rotate(-time * 3);
  ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI * 0.8); ctx.stroke(); ctx.restore();
  ctx.fillStyle = 'rgba(10,8,30,0.85)'; ctx.beginPath(); ctx.arc(x, y, 11, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = col; ctx.strokeStyle = col; ctx.lineWidth = 2.5;
  ctx.beginPath();
  if (pw.kind === 'shield') { ctx.moveTo(x, y - 7); ctx.lineTo(x + 6, y - 4); ctx.lineTo(x + 5, y + 2); ctx.lineTo(x, y + 7); ctx.lineTo(x - 5, y + 2); ctx.lineTo(x - 6, y - 4); ctx.closePath(); ctx.fill(); }
  else if (pw.kind === 'magnet') { ctx.arc(x, y, 5, Math.PI, 0, true); ctx.moveTo(x - 5, y); ctx.lineTo(x - 5, y - 6); ctx.moveTo(x + 5, y); ctx.lineTo(x + 5, y - 6); ctx.stroke(); }
  else if (pw.kind === 'boost') { ctx.moveTo(x + 2, y - 8); ctx.lineTo(x - 4, y + 1); ctx.lineTo(x, y + 1); ctx.lineTo(x - 2, y + 8); ctx.lineTo(x + 4, y - 1); ctx.lineTo(x, y - 1); ctx.closePath(); ctx.fill(); }
  else { ctx.moveTo(x, y + 6); ctx.bezierCurveTo(x - 9, y - 1, x - 4, y - 8, x, y - 3); ctx.bezierCurveTo(x + 4, y - 8, x + 9, y - 1, x, y + 6); ctx.fill(); }
}

export function drawPortal(ctx: CanvasRenderingContext2D, x: number, y: number, t: number, p: Palette) {
  const cy = y - 56;
  ctx.globalCompositeOperation = 'lighter';
  ctx.drawImage(glow(p.nebB), x - 110, cy - 110, 220, 220);
  for (let i = 0; i < 5; i++) {
    ctx.save(); ctx.translate(x, cy); ctx.rotate(t * (1 + i * 0.4) * (i % 2 ? -1 : 1)); ctx.scale(0.62, 1);
    ctx.strokeStyle = i % 2 ? p.edge : p.nebB; ctx.globalAlpha = 0.8 - i * 0.12; ctx.lineWidth = 4 - i * 0.5;
    ctx.beginPath(); ctx.arc(0, 0, 50 - i * 8, 0, Math.PI * 1.5); ctx.stroke(); ctx.restore();
  }
  ctx.globalAlpha = 0.9; ctx.drawImage(glow('#ffffff'), x - 26, cy - 40, 52, 80);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.fillStyle = '#20183f'; ctx.fillRect(x - 40, y - 6, 80, 6);
  ctx.fillStyle = p.edge; ctx.fillRect(x - 40, y - 6, 80, 2);
}

export function drawCheckpoint(ctx: CanvasRenderingContext2D, cp: Checkpoint, time: number) {
  const { x, y } = cp, col = cp.active ? '#7cf7ff' : '#ff5d73';
  ctx.fillStyle = '#2a2e4f'; ctx.fillRect(x - 3, y - 64, 6, 64); ctx.fillRect(x - 10, y - 6, 20, 6);
  ctx.fillStyle = '#8890c0'; ctx.fillRect(x - 3, y - 64, 2, 64);
  ctx.globalCompositeOperation = 'lighter';
  const pulse = 1 + Math.sin(time * 5) * 0.15;
  ctx.drawImage(glow(col), x - 26 * pulse, y - 66 - 26 * pulse,52 * pulse, 52 * pulse);
  if (cp.active) {
    const g = ctx.createLinearGradient(0, y - 66, 0, y - 400); g.addColorStop(0, 'rgba(124,247,255,0.35)'); g.addColorStop(1, 'rgba(124,247,255,0)');
    ctx.fillStyle = g; ctx.fillRect(x - 8, y - 400, 16, 334);
  }
  ctx.globalCompositeOperation = 'source-over';
  ctx.fillStyle = col; ctx.beginPath(); ctx.arc(x, y - 66, 7, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(x - 2, y - 68, 2.5, 0, Math.PI * 2); ctx.fill();
}

export function drawMover(ctx: CanvasRenderingContext2D, m: Mover, p: Palette, time: number) {
  const g = ctx.createLinearGradient(0, m.y, 0, m.y + m.h);
  g.addColorStop(0, '#f2f5ff'); g.addColorStop(0.35, '#7b84c4'); g.addColorStop(1, '#262a50');
  ctx.fillStyle = g; ctx.beginPath(); ctx.roundRect(m.x, m.y, m.w, m.h, 4); ctx.fill();
  ctx.fillStyle = p.edge; ctx.fillRect(m.x + 4, m.y, m.w - 8, 2);
  ctx.globalCompositeOperation = 'lighter';
  const f = 0.7 + Math.sin(time * 30) * 0.3;
  for (const ox of [16, m.w - 16]) ctx.drawImage(glow(p.accent), m.x + ox - 10, m.y + m.h - 4, 20, 26 * f);
  ctx.globalCompositeOperation = 'source-over';
}

// ---------- Partículas (pool fijo): chispas, polvo, anillos y textos ----------
export type PKind = 'spark' | 'dust' | 'ring' | 'glow' | 'text';
interface P { kind: PKind; x: number; y: number; vx: number; vy: number; life: number; max: number; size: number; color: string; g: number; text: string }

const MAX = 700;

export class Particles {
  list: P[] = [];
  private pool: P[] = [];

  private get(): P {
    return this.pool.pop() ?? { kind: 'spark', x: 0, y: 0, vx: 0, vy: 0, life: 0, max: 1, size: 1, color: '#fff', g: 0, text: '' };
  }
  add(kind: PKind, x: number, y: number, vx: number, vy: number, life: number, size: number, color: string, g = 0, text = '') {
    if (this.list.length >= MAX) return;
    const p = this.get();
    p.kind = kind; p.x = x; p.y = y; p.vx = vx; p.vy = vy; p.life = life; p.max = life; p.size = size; p.color = color; p.g = g; p.text = text;
    this.list.push(p);
  }
  burst(x: number, y: number, n: number, color: string, speed = 260, size = 3, g = 500) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2, s = speed * (0.3 + Math.random() * 0.7);
      this.add('spark', x, y, Math.cos(a) * s, Math.sin(a) * s, 0.35 + Math.random() * 0.5, size * (0.6 + Math.random() * 0.8), color, g);
    }
  }
  dust(x: number, y: number, n: number, dir = 0) {
    for (let i = 0; i < n; i++) {
      this.add('dust', x + (Math.random() - 0.5) * 16, y, (Math.random() - 0.5) * 120 + dir * 80, -Math.random() * 70, 0.35 + Math.random() * 0.3, 3 + Math.random() * 4, 'rgba(200,210,255,0.55)', -40);
    }
  }
  ring(x: number, y: number, color: string, size = 40, life = 0.4) { this.add('ring', x, y, 0, 0, life, size, color); }
  text(x: number, y: number, t: string, color = '#ffe66d') { this.add('text', x, y, 0, -70, 0.9, 16, color, 0, t); }
  clear() { while (this.list.length) this.pool.push(this.list.pop()!); }

  update(dt: number) {
    const L = this.list;
    for (let i = L.length - 1; i >= 0; i--) {
      const p = L[i];
      p.life -= dt;
      if (p.life <= 0) { L[i] = L[L.length - 1]; L.pop(); this.pool.push(p); continue; }
      p.vy += p.g * dt; p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.kind === 'dust') { p.vx *= 0.92; p.vy *= 0.92; }
    }
  }

  draw(ctx: CanvasRenderingContext2D) {
    ctx.save();
    for (const p of this.list) {
      const k = p.life / p.max;
      if (p.kind === 'dust') {
        ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = k; ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * (1.4 - k * 0.6), 0, Math.PI * 2); ctx.fill();
      } else if (p.kind === 'text') {
        ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = Math.min(1, k * 2);
        ctx.font = '900 16px "Trebuchet MS", system-ui, sans-serif'; ctx.textAlign = 'center';
        ctx.lineWidth = 4; ctx.strokeStyle = 'rgba(10,5,30,0.8)'; ctx.strokeText(p.text, p.x, p.y);
        ctx.fillStyle = p.color; ctx.fillText(p.text, p.x, p.y);
      } else {
        ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = k;
        if (p.kind === 'ring') {
          ctx.strokeStyle = p.color; ctx.lineWidth = 3 * k + 1;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size * (1.2 - k), 0, Math.PI * 2); ctx.stroke();
        } else if (p.kind === 'glow') {
          const s = p.size * (0.5 + k); ctx.drawImage(glow(p.color), p.x - s, p.y - s, s * 2, s * 2);
        } else {
          ctx.strokeStyle = p.color; ctx.lineWidth = p.size; ctx.lineCap = 'round';
          ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x - p.vx * 0.03, p.y - p.vy * 0.03); ctx.stroke();
        }
      }
    }
    ctx.restore();
  }
}

// Tipos compartidos del juego.
export const TS = 32; // tamaño de casilla en píxeles de mundo
export const ROWS = 18;
export const VIEW_H = ROWS * TS; // altura de mundo visible

export type DiffKey = 'facil' | 'normal' | 'dificil';
export interface DiffCfg { label: string; sub: string; lives: number; enemySpeed: number; gap: number; density: number; fire: number }
export const DIFFS: Record<DiffKey, DiffCfg> = {
  facil: { label: 'Cadete', sub: '5 vidas · enemigos lentos', lives: 5, enemySpeed: 0.75, gap: 0, density: 0.35, fire: 0.7 },
  normal: { label: 'Piloto', sub: '3 vidas · equilibrado', lives: 3, enemySpeed: 1, gap: 0.5, density: 0.5, fire: 1 },
  dificil: { label: 'Leyenda', sub: '2 vidas · abismos y fuego', lives: 2, enemySpeed: 1.3, gap: 1, density: 0.7, fire: 1.35 },
};

export interface Palette { name: string; sky0: string; sky1: string; nebA: string; nebB: string; rock: string; rockDark: string; edge: string; accent: string; planet: string }

export type PowerKind = 'shield' | 'magnet' | 'boost' | 'life';
export type EnemyKind = 'crawler' | 'floater' | 'turret' | 'spiker';

export interface Coin { x: number; y: number; taken: boolean; t: number }
export interface Power { x: number; y: number; kind: PowerKind; taken: boolean; t: number }
export interface Enemy {
  kind: EnemyKind; x: number; y: number; w: number; h: number; vx: number; dir: number;
  x0: number; x1: number; baseY: number; t: number; cool: number; alive: boolean; flash: number;
}
export interface Bullet { x: number; y: number; vx: number; vy: number; life: number }
export interface Mover { x: number; y: number; w: number; h: number; x0: number; y0: number; ax: number; ay: number; speed: number; t: number; dx: number; dy: number }
export interface Checkpoint { x: number; y: number; active: boolean; t: number }

export interface Level {
  index: number; name: string; w: number; h: number; tiles: Uint8Array;
  coins: Coin[]; powers: Power[]; enemies: Enemy[]; movers: Mover[]; checkpoints: Checkpoint[];
  portal: { x: number; y: number }; spawn: { x: number; y: number }; palette: Palette; totalCoins: number;
}

export interface Player {
  x: number; y: number; w: number; h: number; vx: number; vy: number; face: number;
  onGround: boolean; coyote: number; buffer: number; airJumps: number; jumpHeld: boolean;
  dashT: number; dashCd: number; canDash: boolean; dashDir: { x: number; y: number };
  sx: number; sy: number; invuln: number; dead: boolean; deadT: number; riding: Mover | null;
  trail: { x: number; y: number; face: number; a: number }[]; runT: number; flame: number;
  shield: boolean; magnet: number; boost: number;
}

export interface HudState {
  score: number; coins: number; totalCoins: number; lives: number; level: number; sector: string; time: number;
  shield: boolean; magnet: number; boost: number; dashReady: boolean; progress: number;
}
export interface EndStats { score: number; coins: number; level: number; enemies: number; time: number; hi: number; newRecord: boolean }

.se-root { font-family: 'Trebuchet MS', 'Segoe UI', system-ui, sans-serif; color: #eef2ff; }
.se-title {
  font-weight: 900; font-style: italic; letter-spacing: -0.02em; line-height: 0.9;
  background: linear-gradient(180deg, #ffffff 0%, #b9f6ff 45%, #7cf7ff 55%, #ff5ea8 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 0 #1b0f45) drop-shadow(0 0 24px rgba(124, 247, 255, 0.45));
}
.se-panel {
  background: linear-gradient(160deg, rgba(30, 18, 70, 0.82), rgba(8, 6, 28, 0.88));
  border: 1px solid rgba(124, 247, 255, 0.28);
  box-shadow: 0 0 0 1px rgba(255, 94, 168, 0.12), 0 20px 60px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
}
.se-btn {
  background: linear-gradient(180deg, #ffe066, #ff9f1c); color: #2a1200; font-weight: 900; letter-spacing: 0.04em;
  box-shadow: 0 6px 0 #a3450c, 0 0 30px rgba(255, 210, 63, 0.45); transition: transform 0.08s, box-shadow 0.08s;
}
.se-btn:hover { transform: translateY(-2px); }
.se-btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #a3450c, 0 0 20px rgba(255, 210, 63, 0.4); }
.se-ghost { background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(124, 247, 255, 0.3); transition: background 0.15s; }
.se-ghost:hover { background: rgba(124, 247, 255, 0.16); }
.se-chip { text-shadow: 0 1px 0 rgba(0, 0, 0, 0.6); }
@keyframes se-float { 0%, 100% { transform: translateY(0) rotate(-2deg); } 50% { transform: translateY(-8px) rotate(2deg); } }
.se-float { animation: se-float 3.2s ease-in-out infinite; }
@keyframes se-pop { 0% { opacity: 0; transform: translateY(16px) scale(0.92); } 100% { opacity: 1; transform: none; } }
.se-pop { animation: se-pop 0.45s cubic-bezier(0.2, 1.4, 0.4, 1) both; }
@keyframes se-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.45; } }
.se-pulse { animation: se-pulse 1.1s ease-in-out infinite; }
